const D: MvBook[] = [{"u":"Тропарі й кондаки Господні (додаткові)","e":"Troparia and kontakia of the Lord (additional)","secs":[{"ps":["Я́коже ви́шнія тве́рди благолі́піє, / і ни́жнюю споказа́л єси́ красоту́ свята́го селе́нія сла́ви Твоєя́, Го́споди, / утверди́ сіє́ во вік ві́ка / і прийми́ на́ша в нем непреста́нно приноси́мая Тебі́ моле́нія, Богоро́дицею, // всіх Животі́ і Воскресе́ніє."],"h":"Оновлення храму Воскресіння Христового в Єрусалимі — тропар, глас 4"},{"ps":["Обновле́нія ду́ха в сердця́х / і просвіще́ніє вну́тренним да́руй, / ві́рою соверша́ющим свяще́нная обновле́нія хра́ма до́му Твоєго́, / єму́же благоволи́л єси́ созда́тися в Твоє́ Боже́ственноє і́м'я, // Єди́не во святи́х прославля́ємий."],"h":"Оновлення храму Воскресіння Христового в Єрусалимі — інший кондак, глас 2"},{"ps":["Отве́рзий Небеса́ заключе́нная, на Небесі́ пресві́тлия лучи́, / на землі́ возсія́ Пречи́стий Крест: / ті́мже, сія́ніє єго́ ді́йства приє́мше, к незаходи́мому наставля́ємся Сві́ту / і во бранеіх і́мами єго́ ору́жіє ми́ра, // непобіди́мую побі́ду."],"h":"Явлення на небі Хреста Господнього в Єрусалимі — кондак, глас 4"},{"ps":["І́же на ка́мені ві́ри созда́вий, це́рков Твою́, Бла́же, / к той іспра́ви моле́нія на́ша, / і прийми́ лю́ди во ві́рі вопію́щих Тебі́: / спаси́ ни Бо́же наш, спаси́ ни."],"h":"На освячення храму — тропар, глас 3"},{"ps":["Возду́ха растворе́ніє повелі́нієм Твої́м прелага́яй, Го́споди, / во́льний дождь с благорастворе́нними возду́хи да́руй землі́, / є́же приноси́ти лю́дем Твої́м плоди́ ізоби́льния, / і насища́ти вся́коє живо́тно Твої́м благоволе́нієм, // моли́твами Богоро́диці і всіх святи́х Твої́х."],"h":"Під час безводдя — тропар, глас 2"}],"notes":[]},{"u":"Тропарі й кондаки Богородичні (додаткові)","e":"Troparia and kontakia of the Theotokos (additional)","secs":[{"ps":["Днесь безча́дія у́зи разріша́ються, / Іоаки́ма бо і А́нну усли́шав Бог, / па́че наде́жди, / роди́ти тім я́ві обіщава́єть Богоотрокови́цю, / із Нея́же Сам роди́ся Неопи́санний, / Челові́к бив, А́нгелом повелі́во вопи́ти Єй: // ра́дуйся. Благода́тная, Госпо́дь с Тобо́ю."],"h":"Зачаття праведною Анною Пресвятої Богородиці — тропар, глас 4"},{"ps":["Одія́ніє всім ві́рним нетлі́нія, Богоблагода́тная Чи́стая, дарова́ла єси́, / свяще́нную ри́зу Твою́, / є́юже свяще́нноє ті́ло Твоє́ покрива́ла єси́, / покро́ве всіх челові́ков, / єя́же положе́ніє пра́зднуєм любо́вію, / і вопіє́м со стра́хом Ті, Чи́стая: // ра́дуйся, Ді́во, христия́н похвало́."],"h":"Покладення чесної ризи Пресвятої Богородиці у Влахерні — кондак, глас 4"},{"ps":["В пресла́внім явле́нії Твоє́м, Ді́во Богоро́дице, / припаде́ к стопа́м Твої́м преподо́бний а́вва Се́ргій / і мольбу́ о святі́й оби́телі ізря́дно сотвори́, / да Твої́м Ма́тернім ко Христу́ предста́тельством / усе́рдно при́сно хода́тайствуєши / о всіх под свяще́нний покро́в Твой прибіга́ющих, // прося́щи нам оставле́нія гріхо́в і ве́лія ми́лости."],"h":"Явлення Пресвятої Богородиці прп. Сергію Радонезькому — тропар, глас 4"}],"notes":[]},{"u":"Тропарі іконам Пресвятої Богородиці (додаткові)","e":"Troparia of the icons of the Theotokos (additional)","secs":[{"ps":["Ра́дуйся, свята́я гора́ Кра́сная, небесі́ подо́бная, / сла́ва бо Бо́жия на Тебі́ возсія́. / Взигра́йте, го́ри і хо́лми, весе́лієм, / я́ко на сей го́ре іко́на Бо́жия Ма́тере, / честна́го Єя́ умиле́нія, просла́вися. / Лику́йте, челові́ци, і веселі́теся. / я́ко нам дарова́ся бога́тство неот'є́млемоє, ісціле́нії сокро́вище, / гла́си, я́коже труби́, возшумі́те, / прославля́юще Єя́ чудеса́ пресла́вная. / І Ти, Чи́стая, ра́дуйся, я́ко с Тобо́ю Госпо́дь."],"h":"Ікона Пресвятої Богородиці Красногорська (Володимирська) — тропар, глас 2"}],"notes":[]},{"u":"Тропарі пророкам","e":"Troparia of the prophets","secs":[{"ps":["І́же во пло́ті А́нгел, / і проро́ков нача́льнику свиді́тельствова, сла́вний Єлиссе́є, / ди́вни чудеса́ соді́лал єси́, проро́че, / поспе́шеством Свята́го Ду́ха; / си́лою Іліїно́ю ісціли́во во́дноє єстество́, / зві́ри же погуби́, пожира́ющия, / і Неєма́на очи́сти, / і вдови́ча си́на воскреси́л єси́, // і всім чту́щим тя да́руй благода́ть і ісціле́ніє."],"h":"Пророку Єлисею, глас 4"},{"ps":["От ма́тере умоле́нний, тезоімені́те да́нія Бо́жия, / от Бо́га зва́нія во младе́нчестві сподо́бися, / честни́й проро́че Саму́їле, / до́брі паси́й непокори́вия лю́ди / і царе́м яви́вийся устрої́тель, / і о нас, ві́рно чту́щих тя, моли́ І́стиннаго Бо́га, // да спасе́ть ду́ші на́ша."],"h":"Пророку Самуїлу, глас 5"}],"notes":[]},{"u":"Тропарі апостолам","e":"Troparia of the apostles","secs":[{"ps":["Ри́ма не оста́вль, к нам прише́л єси́, / честни́ми вери́гами, я́же носи́л єси́, апо́столов первопресто́льне. / І́мже ві́рою покланя́ющеся, мо́лимся: / твої́ми к Бо́гу моли́твами // да́руй нам ве́лію ми́лость."],"h":"Апостолу Петру (поклоніння чесним веригам ап. Петра), глас 4"},{"ps":["Учени́че Па́влов і апо́столе Христо́в, Архи́ппе, / Єва́нгелія провозві́стниче і Колосса́єв учи́телю, / ка́менноє побіє́ніє приє́мий, / а́ки драгоці́нноє украше́ніє, / і́мже віне́ць муче́нія украси́в, вшел єси́ на весе́ліє Ца́рствія, / іді́же пом'яни́ нас пою́щих твою́ па́м'ять, // апо́столов сопресто́льниче."],"h":"Апостолу від сімдесяти Архиппу, глас 3"},{"ps":["Лик п'яточи́сленний апо́стол Христо́вих пі́сньми восхва́лим, / Си́лу, Силуа́на, Криске́нта, Андрони́ка со Єпене́том, / сі́ї бо і́дольськую лесть обличи́ша / і, неві́рния во ві́ру улови́вше, // мо́лять непреста́нно о всіх, па́м'ять їх велича́ющих."],"h":"Апостолам від сімдесяти Сілі, Силуану, Криску, Єпенету й Андронику, глас 3"},{"ps":["Днесь Єде́с град весели́ться, / приє́м тобо́ю Креще́нія ба́ню, / і А́вгар, страсте́й преміне́н, твою́ па́м'ять сла́вить. / С ни́миже поє́м і ми: / весе́лія духо́внаго іспо́лни живо́т наш / і стра́сті ісціли́, // Фадде́є апо́столе, моли́твами твої́ми."],"h":"Апостолу від сімдесяти Фаддею, глас 2"}],"notes":[]},{"u":"Тропарі рівноапостольним","e":"Troparia of the equals-to-the-apostles","secs":[{"ps":["Досто́йнейший преє́мник учи́теля своєго́ Мефо́дія, / Мора́вськия Це́ркве первопресто́льника, / бил єси́, святи́телю о́тче наш Гора́зде, / столп Правосла́вія преди́вен, / му́ченик без кро́ве, / і ізгна́ніє от своєго́ ста́да кова́рними му́жи претерпі́в. / Дале́че от своєго́ оте́чества, Мора́вськия землі́, / утверди́в про́повідію догма́ти Боже́ственния І́стини, / Ду́хом соєдини́лся єси́ со святи́ми учи́тели свої́ми Кири́ллом і Мефо́дієм в Ца́рстві Небе́снім. / Моли́ о нас, блаже́нне, / ві́рою почита́ющих па́м'ять твою́, // умири́ти мир і спасти́ ду́ші на́ша."],"h":"Горазду, архієпископу Моравському, глас 2"},{"ps":["Словеси́ наста́вил єси́ язи́ки во ві́ру Христо́ву, / ді́ли же возви́сил єси́ себе́ к Боже́ственній жи́зні, / святи́телю Кли́менте равноапо́стольне, / чудеси́ сія́я приступа́ющим к тебі́ ві́рно / і зна́меньми озаря́я Це́рков пресла́вно, // сего́ ра́ди честну́ю твою́ па́м'ять сла́вим."],"h":"Клименту, архієпископу Охридському, глас 4"},{"ps":["Вінці́ хвале́нія увінча́їм седьмочи́сленники сла́вния, / Кири́лла со Мефо́дієм, Кли́мента, Нау́ма со Са́ввою / і Гора́зда со Ангела́рієм, / я́ко світи́ла возсія́вшия / і Трієди́наго Бо́га нам благовести́вшия, / столпи́ нези́блемия Це́ркве Бо́лгарськия / і богодухнове́нния побо́рники сло́ва на́шего, / бісо́вськоє і́долом поклоне́ніє упраздни́вшия / і Христу́ Бо́гу моля́щіяся, / Це́рков на́шу утверди́ти / і душа́м на́шим дарова́ти // мир і ве́лію ми́лость."],"h":"Кирилу, Мефодію, Клименту, єпископу Охридському, Науму, Саві, Горазду й Ангеляру (болгарські), глас 1"},{"ps":["Святи́теля Твоєго́, Христе́, / творя́щим сві́тло торжество́ успе́нія / ми́лость Твою́ сви́ше пода́ждь, / отве́рзи же Ца́рствія две́рі, / разріши́ же у́зи на́ша мно́гих гріхо́в / хода́тайством свята́го Твоєго́ ученика́, // отця́ на́шего."],"h":"Мефодію, архієпископу Моравському, глас 4"},{"ps":["Мир оста́вил єси́, приліпи́вся Христу́, / плоть расп'я́л єси́, пожи́в Ду́ху, / Нау́ме всеблаже́нне, / потща́лся єси́ апо́стольським подвиза́тися тече́нієм / і улови́л єси́ к ві́рі Бо́лгарськая неісче́тная мно́жества. / Ті́мже моли́твами твої́ми // ізба́ви нас от іскуше́ній."],"h":"Науму Охридському, глас 4"}],"notes":[]},{"u":"Тропарі святителям","e":"Troparia of the hierarchs","secs":[{"ps":["От мирська́го м'яте́жа ізше́д, / в пеще́рах Ки́євських Феодо́сія блаже́ннаго Богому́дренно всели́лся єси́. / святи́телю Христо́в, о́тче Амфіло́хіє, / і отсю́ду во єпи́скопа Богоспаса́ємій па́стві Влади́миро-Воли́нстій поста́вленний, / в труді́х, бді́ніїх і поще́ніїх свя́то подвиза́лся єси́. / І та́ко дости́г доброді́телей соверше́нства, / па́ки в пеще́ри святи́я возврати́лся єси́, / іді́же і дух свой благоче́стно преда́л єси́ Го́сподеві, всече́стне, / к ли́ку преподо́бних Пече́рських причте́н, / с ни́ми же моли́ся Христу́, всече́стне, // спасти́ся душа́м на́шим."],"h":"Амфілохію, єпископу Володимир-Волинському, глас 4"},{"ps":["Чистоти́ житія́ сві́том стра́стноє те́рніє попали́л єси́ / і тече́нієм слез безпло́дную зе́млю напої́л єси́, / многопло́дну ни́ву душе́вную соді́лав, / Афана́сіє треблаже́нне, / світи́ло Царюгра́ду, Патріа́рхом удобре́ніє, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Афанасію, патріарху Цареградському, глас 1"},{"ps":["Равноапо́стольному святи́телю Стефа́ну наслі́довавшії / і Правосла́вія сві́том страну́ Зиря́нськую озари́вшії, / святи́теліє Христо́ви Гера́симе, Питири́ме і Іо́но, / Престо́лу Пресвяти́я Тро́йці ни́ні предстоя́ще, / молі́теся па́стві ва́шей от враго́в ненаві́тованній би́ти // і всім правосла́вним лю́дем в ми́рі спасти́сь."],"h":"Герасиму, Пітіріму й Іоні, єпископам Великопермським і Устьвимським, глас 8"},{"ps":["Я́ко крин благово́нний, / мироточи́вия твоя́ мо́щі / от вертогра́да Це́ркве Спа́сови / во вертогра́д Це́ркве Богоро́дични че́стне принесо́шася, / святи́телю Гу́ріє, / я́ко же бо дар че́стен, / тя дарова́в Христо́с Пречи́стій Ма́тері Своє́й, / і іспо́лнися храм Єя́ святи́й благоуха́нія твоєго́, / і возра́довася архієре́йський престо́л, / приє́мий тя, первосіда́теля своєго́. / Возвесели́ся же собо́р ві́рних со святи́телем і священнонача́льники / о пресла́вном цільбоно́сних твої́х моще́й пренесе́нії, / є́же ми ра́достно пра́зднующе, мо́лим тя, уго́дниче Бо́жий: / моли́ Христа́ Бо́га // пода́ти душа́м на́шим мир і ве́лію ми́лость."],"h":"Гурію, архієпископу Казанському, глас 4"},{"ps":["Чу́до яви́ся ізвіще́нія, / діла́ми доброді́телей Бо́жиїх возсія́л єси́, / мона́шествующих ли́ки упа́сл єси́, / архієре́йськая сіда́лища утверди́л єси́, / єреті́чеськаго нападе́нія не усумні́вся, / Це́рковію Христо́вою управля́я, / преподо́бне о́тче, Данії́ле прему́дре, / усну́в, я́ко сп'я, / ті́ло же твоє́ ці́ло і нетлі́нно соблюде́но бисть, / і подає́ть цільби́ боля́щим от разли́чних неду́гов, / і де́мони прогоня́єть. / Сего́ ра́ди мо́лим тя: // моли́ спасти́ся душа́м на́шим."],"h":"Даниїлу, архієпископу Сербському, глас 3"},{"ps":["Я́коже дре́вле на Восто́ціх тріє́ вели́ції святи́теліє, / си́льний сло́вом Васи́лій, / глубина́ Богосло́вія Григо́рій і Златоу́стий Іоа́нн, / та́ко і днесь в страні́ полу́нощній / три новоявле́нная світи́ла ві́ри на тве́рди церко́вній востеко́ша: / столп ві́ри Митрофа́н, / сло́во і́стини в лиці́ царю́ іспові́давий, / і обличи́тель раско́ла Дими́трій, / мече́м обою́ду о́стрим вся ко́зні єго́ разсеки́й, / і пома́занія по́лний сосу́д Ти́хон, / ти́хостію слове́с свої́х грі́шника к покая́нію призва́вий. / О вели́ції тріє́ святи́теліє землі́ Россі́йськия, / молі́те Христа́ Бо́га, Єму́же уго́дні би́сте, // спасти́ся душа́м на́шим."],"h":"Димитрію, митрополиту Ростовському, Мітрофану й Тихону, єпископам Воронезьким, глас 8"},{"ps":["Блаже́н ді́латель і украси́тель Це́ркве Христо́ви, / о́тче Дона́те, бил єси́, / непреста́нно попече́ніє о ста́ді твоє́м стяжа́в, / науча́я і руководя́ о́но в любві́ Си́на Бо́жия, / не то́кмо бо в твоє́м гра́де мно́гий наро́д, / но в Константино́полі самоде́ржця і в нем вся лю́ди / удиви́л єси́ / пресла́вними чудеси́ твої́ми. / Богоуго́дния у́бо мольби́ / сотворя́я ко Христу́ Бо́гу, / помо́щник скор всім яви́ся, / предстоя́ Всесвяті́й Тро́йце, / во Ви́шніх моли́ Ю о всіх нас, // да спасе́ть ду́ші на́ша."],"h":"Донату, єпископу Євріїському, глас 4"},{"ps":["Патріа́рхов вели́коє удобре́ніє, / святи́телем красото́, мона́хом пра́вило, / пусти́нником сла́ву, ми́лости пода́теля, / разсужде́нія світи́льника, / соше́дшеся, ві́рнії, восхва́лим, / кро́тости учи́теля, Боже́ственнаго рачи́теля, / прему́драго архипа́стиря, вели́каго святи́теля і отця́, / Єфре́ма, Патріа́рха Се́рбськаго, / звізду́, те́мния лю́ди просвіща́ющую / і вся ві́рния озаря́ющую. / Ті́мже, притека́юще к ра́ці моще́й єго́, / любо́вію цілу́єм я і вопіє́м: / свя́те святи́й, непреста́й моли́ти Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Єфрему, патріарху Сербському, глас 8"},{"ps":["Чу́до яви́вся ізвіще́нія, / ді́ли возсія́л єси́ доброді́телей Бо́жиїх, / мона́шествующих ли́ки упа́сл єси́, / архієре́йськая сіда́лища ізчи́стил єси́, / єреті́чеськаго же напа́данія не усумні́вся, / це́ркви Христо́ви воздви́гл єси́, / преподо́бне Іларіо́не, / у́мер, я́ко сп'я, / ті́ло же твоє́ ці́ло і нетлі́нно соблюдено́ бисть, / і подає́ть цільби́ боля́щим от разли́чних неду́г, / і де́мони прогоня́єть, / сего́ ра́ди мо́лим тя: // моли́ спасти́ся душа́м на́шим."],"h":"Іларіону, єпископу Меглинському, глас 3"},{"ps":["Воспо́йте у́бо, всі лю́діє, / в Тріє́х Іпоста́сіх Єди́наго Бо́га, / на Небесі́х непости́жно пребива́ющаго, / манове́нієм же вся́чеськая управля́ющаго, / на зе́млю же щедро́тно призира́ющаго, / в пусти́нном же пребива́ющаго проти́ву неви́димих враго́в, / уго́дника Своєго́ преподо́бнаго Іларіо́на укрі́пльшаго, // того́ моли́твами, Бо́же, поми́луй і спаси́ нас."],"h":"Іларіону, митрополиту Суздальському, глас 5"},{"ps":["Управля́я Це́рков Бо́жию Собо́рную і Апо́стольськую, / соблюда́я за́повіді Бо́жия, / вельми́ до́брі упа́с ста́до слове́сних ове́ць; / зломи́сленним церко́вником моли́твою своє́ю прозрі́ти повелі́, / і научи́, я́коже пре́жде святи́й Лео́нтій, / поспі́шник спасе́нію Ру́ськия землі́, учи́тель Росто́вський, / пре́жде связа́ і па́ки благослови́; / та́ко святи́й єпи́скоп Су́ждальський, / напа́стем, притека́ющим к тебі́, ізба́вниче, чудотво́рче Іоа́нне, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Іоанну, єпископу Суздальському, глас 8"},{"ps":["Я́ко апо́столом єдинонра́вних учи́телей Су́ждальськия страни́, / і ціли́телей душ і тіле́с прему́дрих, / і служи́телей Бо́гу благоприя́тних, / к ра́кам честни́х моще́й ва́ших притека́юще, / ублажа́єм вас, святи́теліє Богоблаже́ннії, Фео́доре і Іоа́нне, / в пі́сніх же і пі́ніїх, ра́дующеся, сла́вим Христа́, / дарова́вшаго вам благода́ть ісціле́ній // і гра́ду на́шему Су́ждалю вели́коє во вас утвержде́ніє."],"h":"Іоанну й Феодору, єпископам Суздальським, глас 8"},{"ps":["Бра́та Бо́жия на престо́лі архієре́йства преє́мниче, / свята́го гра́да Ієрусали́ма ієра́рше достохва́льне, / с богому́дрими отці́ в Халкидо́ні із'ясни́л єси́ воплоще́ніє Си́на Бо́жия, / прише́дшаго мир обнови́ти і обожи́ти вся челові́ки, / в Це́ркві Єго́ с Ним сочета́вшіяся, / святи́телю о́тче Іувена́ліє, / предстоя́ ни́ні во Ца́рствії Отця́ сві́тов, / о почита́ющих тя любо́вію моли́ся, // да мир і ми́лость Спа́сова бу́деть с нам."],"h":"Ювеналію, патріарху Єрусалимському, глас 4"},{"ps":["Благоче́стія ревни́телю і рачи́телю, / і́ноков і сто́лпников похвало́, / святи́телю Ту́ровськия па́стви, пресла́вне, / златослове́сний учи́телю, / сві́тлим уче́нієм Богоразу́мія своєго́ просвіти́вий конці́ ру́ськия, / в моли́тві к Бо́гу благода́тний грі́шников споспі́шниче, / Кири́лле Богому́дре, моли́ Христа́ Бо́га / утверди́тися нам, сооте́чественником твої́м, // во Правосла́вії, благоче́стії і єдиноми́слії."],"h":"Кирилу, єпископу Туровському, глас 4"},{"ps":["Апо́столом соприча́стник / і к Бо́гу моле́бник ві́рен, / доброді́тельми возше́д на Небе́сная, / і любо́во возложи́л єси́ к Лю́б'ящему тя, / і неві́рния лю́ди обрати́л єси́ во ві́ру. / Тім ни́ні со А́нгели лику́я, / предстої́ши Престо́лу сла́ви всіх Царя́ Христа́ Бо́га: / моли́ся, святи́телю Лео́нтіє, // да спасе́ть ду́ші на́ша."],"h":"Леонтію, єпископу Ростовському, глас 4"},{"ps":["Стра́нноє рожде́ніє і воспита́ніє бил єси́ о́тче, / но па́ки водвори́ся во вла́сті у своєго́ наро́да, / Небе́снаго Ца́рствія жела́я, / земно́є ца́рствіє оста́вил єси́ / і смире́нієм Ви́шнєє сокро́вище получи́л єси́, / преблаже́нне Макси́ме, // моли́, мо́лимся, о душа́х на́ші."],"h":"Максиму Новому, колишньому деспоту Сербському, глас 3"},{"ps":["І́стинних повелі́ній устні́ распространи́л єси́, / уче́нії Боже́ственними вся просвіти́л єси́, / злові́ріє низложи́л єси́, Богому́дре Марти́не, / святи́телю всече́стне, / помина́й нас, уго́дниче Христо́в, / є́же к Нему́ хода́тайстви твої́ми, // да в ми́рі устро́їши живо́т наш."],"h":"Мартину Сповіднику, папі Римському, глас 4"},{"ps":["Преподо́бно пожи́в, Богому́дре Моде́сте, / і святи́тельською оде́ждою укра́шен, / па́стирю Ієрусали́ма блаже́ннійший, / во весе́лії ни́ні Христу́ предстої́ши / і конці́ озаря́єши чудеси́, / помо́щник у́бо бу́ди тя призива́ющим, // моля́ся, о́тче, о всіх нас."],"h":"Модесту, архієпископу Єрусалимському, глас 4"},{"ps":["Чу́дноє і сла́вноє рождество́ твоє́, святи́телю Нико́лає, / Це́рков днесь правосла́вних сві́тло пра́зднуєть, / і́бо стоя́нієм ногу́ твоє́ю / яви́ тя Госпо́дь і провозвісти́ би́ти світи́льника і учи́теля ми́ряном, / весь мир обогаща́юща і просвіща́юща чудеси́. / Тім вопіє́м ті: // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Миколаю, архієпископу Мир Лікійських, чудотворцю, глас 4"},{"ps":["Пресві́тлий хра́мі Свята́го Ду́ха, / Богому́дре о́тче Нико́лає, / благода́тію Небе́с освяти́ ду́ші на́ша, / заступи́ і покри́й всечестни́м твої́м омофо́ром, / єго́ же прия́л єси́ от рук Пречи́стия Ді́ви, / і просвіти́ нас сві́том за́повідей Христа́, / от Него́ бо прия́л єси́ глаго́ли жи́зні. / Моли́ бла́гость Отця́ Небе́снаго, / во є́же спасти́ся / правосла́вно чту́щим тя, // да́руя нам ве́лію ми́лость."],"h":"Миколаю, архієпископу Мир Лікійських, чудотворцю, інший тропар, глас 4"},{"ps":["Я́ко драгоці́нноє бога́тство, / приї́де к нам от Вели́кия ріки́ В'я́тки / в ца́рствующий сей град наш Москву́ / честна́я іко́на о́браза твоєго́, святи́телю Нико́лає, / і мно́гая у́бо чудеса́ в прише́ствії своє́м сотвори́, / боля́щия ісціли́ і вся челові́ки удиви́. / Сего́ ра́ди повелі́нієм самоде́ржця царя́ / списа́ся с нея́ сія́ честна́я іко́на твоя́ / на просвіще́ніє і моле́ніє всім лю́дем ца́рська гра́да, / ю́же днесь зрим і покланя́ємся єй, / моля́ще тя, таї́нника Христо́ва: / моли́, свя́те, о всіх нас, // дарова́ти нам мир і ве́лію ми́лость."],"h":"Миколаю, архієпископу Мир Лікійських, чудотворцю, ще один тропар, глас 3"},{"ps":["Я́ко сий нра́вом правосла́вних / Восто́чния Це́ркве преда́ній і́стинний защи́тник, / сподо́бился єси́ вели́каго во отці́х Феодо́сія / ви́діти по сме́рті, я́ко жи́ва, / возвіща́юща тебі́ Ца́рствія Небе́снаго наслі́діє, / єго́же неізрече́нних добро́т / ни́ні с ним неразлу́чно наслажда́яся, // моли́ і о нас, ча́діх свої́х, Ни́фонте прехва́льне."],"h":"Нифонту, єпископу Новгородському, глас 3"},{"ps":["Боже́ственния ві́ри іспові́данієм / друга́го Па́вла тя Це́рков, ревни́теля во свяще́нниціх, показа́, / свозопіє́ть ті і А́вель ко Го́споду, / і Заха́ріїна кров пра́ведная. / О́тче преподо́бне, Христа́ Бо́га моли́ // дарова́тися нам ве́лієй ми́лости."],"h":"Павлу, патріарху Константинопольському, сповіднику, глас 3"},{"ps":["І́же Боже́ственним нача́лом прему́дрости, / стра́хом Госпо́днім утве́рждся, / отту́ду свяще́нними восхожде́нії возше́л єси́ / во учени́чество Златоу́ста, / і архієре́йськаго того́ престо́ла досто́їн бив чистоти́ добро́тами, / апо́стольським пра́вилом себі́ вообрази́в, / не себі́ живи́й, но Христу́ і ста́ду твоєму́. / Тім в нетлі́нний живо́т апо́стольськи всели́лся єси́, / ієра́рше Про́кле, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Проклу, архієпископу Константинопольському, глас 4"},{"ps":["Я́ко святи́тель со Безпло́тними єдиножи́тель бив, / священному́чениче Стефа́не, / восприє́м бо Крест я́ко ору́жіє, / і став крі́пко сопроти́в іконоукори́теля і духобо́рцев, / не покланя́ющихся пречи́стому о́бразу Христа́ Бо́га на́шего, / і отсі́кл єси́ вся́ку є́ресь лука́вих. / Того́ ра́ди приє́м муче́нія віне́ць, / ізба́вил єси́ град твой Суро́ж от вся́кия неприя́зні. / І ни́ні мо́лим тя, свя́те, / да ізба́виши нас от вся́ких злих іскуше́ній, і бід, // і ві́чния му́ки."],"h":"Стефану Сповіднику, архієпископу Сурозькому, глас 4"},{"ps":["Нево́лею па́ству святи́тельськую приї́м, / но во́лею подви́гнувся о Бо́жії Це́ркві, / і пе́рстію Христо́ва гро́ба неві́рнаго Моа́вія царя́ уві́рив, / і с тіле́сною сліпото́ю вку́пі і душе́вную єму́ ісціли́в, благові́рна показа́, / с ни́мже і єретики́ от Бо́жия Це́ркве, я́ко во́лки, отгна́в, / честни́й святи́телю Фео́доре, // моли́ спасти́ся душа́м на́шим."],"h":"Феодору, єпископу Едеському, глас 4"},{"ps":["От ю́ности, прему́дре, прилі́жно подвиза́вся, / і ізвіще́нієм Свята́го Ду́ха / превели́кую оби́тель воздви́же Пресвяті́й Богоро́дице / в похвалу́ Рождества́ Єя́, / струя́ми же слез твої́х безпло́тния враги́ погрузи́л єси́, / і, житія́ твоєго́ цілому́дрієм со А́нгельськими ли́ки совокупи́вся, / преподо́бне о́тче Фео́доре, / с ни́ми же Христа́ Бо́га моли́ // спасти́ся душа́м на́шим."],"h":"Феодору, архієпископу Ростовському, глас 5"},{"ps":["Бо́жия Сло́ва Прему́дрости ізря́дний служи́тель, / А́нгельськаго жи́тельства і́стинний подража́тель, / Боже́ственния чистоти́ рачи́тель, / архієре́ом сопресто́льниче, преподо́бним сожи́тельниче, / па́стирськая красота́, / Вели́кому Но́вугра́ду похвала́, / святи́телю пречестни́й Феокти́сте, о́тче наш, / Єму́же, Сло́ву Бо́жию, в житії́ сем послужи́л єси́, // моли́ спасти́ся душа́м на́шим."],"h":"Феоктисту, архієпископу Новгородському, глас 3"},{"ps":["Слове́с єва́нгельських послу́шателю / і Боже́ственних уче́ній рачи́телю, / прему́дрий наказа́телю, / всегда́ стра́ху Госпо́дню поуча́яйся, / в моли́твах к Бо́гу простира́яйся, / загради́телю уст кривоглаго́лющим сло́во пра́вия ві́ри, / апо́столом соприча́стниче, / ві́рі Христо́вой утверди́телю, / проро́чеськи веща́телю, святи́телю Фо́тіє, / моли́ Христа́ Бо́га // умири́ти мир і спасти́ ду́ші на́ша."],"h":"Фотію, митрополиту Київському і всієї Русі, глас 4"}],"notes":[]},{"u":"Тропарі преподобним","e":"Troparia of the venerable saints","secs":[{"ps":["Зра́ки ізобразу́я святи́х на дщи́цях, / сих благодія́нія спі́шно, / я́ко іску́сен худо́жник, всехва́льне Алі́піє, / написова́л єси́ на скрижа́ліх твоєго́ се́рдця, / і сего́ ра́ди, а́ки о́браз, благолі́пні укра́шен, / свяще́нства благода́тію, а́ки зла́том, обложи́лся єси́ // от Христа́ Бо́га і Спа́са душ на́ших."],"h":"Аліпію, іконописцю Печерському, у Ближніх печерах, глас 8"},{"ps":["Єгда́ ізше́л єси́ от ми́ра, / тогда́ мирська́я вся я́ко тще́тна отве́ргл, / єгда́ же о́браз і́ночеський на ся прия́т, / тогда́ вра́жия кова́рства по́двиги свої́ми і труди́, Аммо́не блаже́нне, попра́л єси́, вопія́: // Христе́ Бо́же, сла́ва Тебі́."],"h":"Аммону, затворнику Печерському, у Дальніх печерах, глас 2"},{"ps":["Світи́льники сві́тлия я́вльшеся, / добро́ту земну́ю му́дренно оста́вльше, / і ідо́ша во вну́треннюю пусти́ню, Амфіло́хіє, Мака́ріє, Тара́сіє і Феодо́сіє, / смире́ніє і вся́кую доброді́тель ізви́кше, / і обріто́ша безсме́ртіє, / посто́м і бді́нієм і про́чим воздержа́нієм себі́ принося́ще Христу́, / і ни́ні на Небесі́х Престо́лу Христо́ву предстої́те. / Молі́те, отці́ Богому́дрії, Амфіло́хіє, Мака́ріє, Тара́сіє і Феодо́сіє, / умири́ти мир і спасти́ся душа́м пою́щих вас, / і согріше́ній оставле́ніє дарова́ти // чту́щим всечестну́ю па́м'ять ва́шу."],"h":"Амфілохію, Макарію, Тарасію й Феодосію Глушицьким, глас 8"},{"ps":["Доброді́тельми бога́тая, / кро́тостію і благоче́стієм укра́шенная, / возсія́ла єси́ чистото́ю житія́ твоєго́, / сего́ ра́ди Благи́й Бог благослови́ тя / би́ти ма́терію світи́льника ро́да се́рбськаго, / ті́мже вопіє́м ті: // ра́дуйся, преподо́бная ма́ти Анастасі́є."],"h":"Анастасії Сербській, глас 4"},{"ps":["Бога́тство твоє́ душе́вноє погуби́ти хотя́ враг, / помрачи́л тя бя́ше бога́тством тлі́нним іспе́рва, / но всіх спаса́яй Госпо́дь / бога́тство ги́бнущеє окра́сти попусти́, / душе́вноє же невре́дно соблю́д, / Небе́сних сокро́вищ наслі́дника тя показа́, Аре́фо, // тім тя чтим і ублажа́єм."],"h":"Арефі, затворнику Печерському, у Ближніх печерах, глас 2"},{"ps":["О́браз Бо́жий в богосотворе́нней душе́ твоє́й, / ум, сло́во, і дух соблюда́я / впери́лся єси́ о́тче преподо́бне Афана́сіє, / любо́вію ко Всетворцю́ Бо́гу, / і сего́ ра́ди / моли́тви, труди́, і по́двиги доброді́тельния восприї́м, / преше́л єси́ во ві́чния небе́сния кро́ви. / Отню́дуже назира́й нас / моля́ Святу́ю Тро́йцю, / є́же наслі́дити нам го́рнєє всера́достноє блаже́нство."],"h":"Афанасію Висоцькому (Молодшому), Серпуховському, глас 8"},{"ps":["Блаже́нство пла́чущих получи́ти жела́я, / день і нощ непреста́нно пла́кал єси́, / імі́я во умі́ час Су́дний, / тім по кончи́ні твоє́й обрі́л єси́ утіше́ніє на Небесі́, / преподо́бне Афана́сіє. / Пода́ждь і нам пла́катися зді гріхо́в на́ших ви́ну, / я́ко да пла́ча безконе́чнаго ізби́вше, // та́мо при́ймем ві́чноє утіше́ніє."],"h":"Афанасію, затворнику Печерському, у Ближніх печерах, глас 3"},{"ps":["Ми́ра кра́сная і сла́ву єго́ оста́вль, / прите́кл єси́ в пеще́ру, / іді́же от си́ли преуспіва́я в си́лу, / бил єси́ вождь Христо́ва ста́да, всесла́вне Варлаа́ме, / є́же я́ко упа́с до́брі, упаси́ і нас, мо́лим тя, // сохраня́я от всіх зол, да тя ублажа́єм."],"h":"Варлааму, ігумену Печерському, у Ближніх печерах, глас 1"},{"ps":["Ізмла́да Христа́ Бо́га чи́сті возлюби́в, / син утіше́нія бил єси́, преподо́бне о́тче Варна́во. / По і́мені і житіє́ твоє́ бисть: / коєму́ждо стра́ждущему, і ни́щу, і царю́, / па́стир кро́ток, уті́шитель і ціли́тель яви́лся єси́. / Помина́й нас, благода́тний о́тче, / да моли́твами те́плими твої́ми / Жизнода́вець Бог да́руєть нам // утіше́ніє і ве́лію ми́лость."],"h":"Варнаві Гефсиманському, глас 5"},{"ps":["Пре́жде отверже́нієм ми́ра, / я́ко морська́го треволне́нія, ізбіго́сте, отці́ преподо́бнії, / по́сліжде же, ізволе́нієм Бо́жиїм, / во вода́х морськи́х кончи́ну блаже́нную прия́сте / і к неболі́зненному поко́ю преста́вистеся от землі́, ра́дующеся. / Тім і по кончи́ні от Христа́ Бо́га просла́вистеся чудеси́ оби́льно, / те́плії в біда́х ві́рним помо́щници показа́стеся, / і ни́ні на Небесі́х предстоя́ще Престо́лу Христо́ву, / Вассія́не преблаже́нне і Іо́но пресла́вне, // молі́теся при́сно о душа́х на́ших."],"h":"Васіану й Іоні Пертомінським, Соловецьким чудотворцям, глас 8"},{"ps":["Добр купе́ць бисть, Богому́дре Веніями́не, / бога́тство бо своє́ тлі́нно разда́в, / купи́л єси́ о́ним нетлі́нноє в Ца́рствії Небе́снім, / в не́мже ни́ні та́мошніх благ наслажда́яся бога́тні, // проси́ нам ми́ра і ве́лія ми́лости."],"h":"Веніамину Печерському, у Дальніх печерах, глас 2"},{"ps":["От ю́ности, богому́дре, просвіти́вся любо́вію Христо́вою, / су́єтний і многом'яте́жний мир оста́вил єси́. / Житіє́ своє́ вве́ря предста́тельству Пречи́стия Богоро́диці, / слез пото́ки ізлива́л єси́ пред честни́м Єя́ о́бразом, / і тече́ньми їх седьм є́зер освяти́л єси́. / І терпі́нія ра́ди украси́ тя небе́сними дара́ми Христо́с Бог наш, / в чудесі́х і учениці́х сла́вна показа́ земле́ Каза́нськой."],"h":"Гавриїлу Седмиозерському, глас 4"},{"ps":["Я́ко Безпло́тним єдинонра́вен / і преподо́бним соо́бщник, преподо́бне Гера́симе, / єди́н на Во́логду прише́л єси́, / прориця́я ту би́ти гра́ду вели́кому / і в нем святі́й це́ркві воздви́гнутися / і святи́телем водвори́тися. / Ті́мже і сподо́бился єси́ / близ того́ погребе́н би́ти / і по преставле́нії своє́м мно́гими чудеси́ ісціле́ній просія́л єси́. / Моли́ся всегда́ о нас, // я́ко да обря́щем от Бо́га ми́лость."],"h":"Герасиму Вологодському, глас 4"},{"ps":["Христо́вих повелі́ній сві́том сердця́ своя́ просвіти́вше, / стра́стний мрак прогна́сте, / ті́мже Тро́йці селе́ніє би́сте тричи́сленнії отці́, / Дамія́не, Ієремі́є с Матфе́єм, / от Нея́же благода́ть приє́мше, / неду́жния ісціля́єте, бу́дущая возвіща́єте / і, А́нгелом соприча́стници су́ще, // молі́теся Христу́ Бо́гу дарова́ти нам прича́стіє святи́х."],"h":"Даміану пресвітеру, цілителю, Єремії й Матфею прозорливим, Печерським, у Ближніх печерах, глас 1"},{"ps":["От ю́ности, блаже́нне, всего́ себе́ Го́сподеві возложи́в, / ви́ну повину́яся Бо́гу, / проти́в'яся же дия́волу, / над страстьми́ гріхо́вними воцари́лся єси́, / тім сам храм Бо́жий бив, / і оби́тель кра́сну во сла́ву Пресвяти́я Тро́йці воздви́гнув, / і со́бранноє тобо́ю в ней ста́до Христо́во Богоуго́дно упа́сши, / преста́вился єси́ к ві́чним оби́телем, / о́тче Данії́ле, // моли́ Триіпоста́снаго во Єди́ном Существі́ Бо́га спасти́ся душа́м на́шим."],"h":"Даниїлу Переяславському, глас 3"},{"ps":["Світи́льници сві́тлия я́вльшеся, / добро́ту земну́ю му́дренно оста́вльше, / і ідо́ша во вну́треннюю пусти́ню, ку́пно с Діони́сієм Амфіло́хіє, / смире́ніє і вся́кую доброді́тель ізвико́ша, і обріто́ша безсме́ртіє, / посто́м і бді́нієм і про́чим воздержа́нієм себі́ принося́ Христу́, / і ни́ні на Небесі́х Престо́лу Христо́ву предстоя́, / молі́теся, отці́ Богому́дрії, Діоні́сіє і Амфіло́хіє, / умири́ти мир і спасти́ся душа́м пою́щих вас, / согріше́нієм оставле́ніє дарова́ти, // чту́щим всечестну́ю па́м'ять ва́шу."],"h":"Діонісію й Амфілохію Глушицьким, глас 8"},{"ps":["Земна́я, прельща́ющая очеса́ миролю́бцев, / возненави́діл єси́, о́тче Богоно́сне Діоні́сіє, / за уме́ти та вміни́в, / ше́ствуя путе́м ско́рбним, / і в терпі́нії добр во́їн Христо́в яви́лся єси́, / побіди́в стра́сті ми́ра, / бил єси́ до кончи́ни непоколеби́мий благоче́стія побо́рник. / Ті́мже ми днесь, соверша́я свяще́нную па́м'ять твою́, / духо́вними тя пі́сньми ублажа́єм і смире́нно мо́лим, / да, предстоя́ Престо́лу Го́спода Бо́га, // хода́тайствуєши о спасе́нії душ на́ших."],"h":"Діонісію Радонезькому, глас 3"},{"ps":["Я́ко сокро́вище многоці́нно / і істо́чник, ізлива́ющ то́ки ісціле́ній, / подаде́ нам Христо́с честни́я мо́щі твоя́, / преподо́бне Євфи́міє, / болі́зні у́бо от'є́млющия страсте́й разли́чних, / благода́ть же душа́м точа́щия непреста́нно, // Єго́же моли́ дарова́ти нам ве́лію ми́лость."],"h":"Євфимію Архангелогородському, глас 4"},{"ps":["Євфи́міє всече́стне, / преподо́бним єдиноревни́телю і А́нгелом собесі́дниче, / получи́вий с ни́ми житіє́м свої́м чи́стим і безмо́лвним ві́чная блага́я, / моли́ся Го́сподеві при́сно о всіх нас, // да і ми тіх же благ сподо́бимся."],"h":"Євфимію, схимнику Печерському, у Дальніх печерах, глас 4"},{"ps":["Пусти́нноє і безмо́лвноє житіє́ ва́ше по́стничеськи препроводи́вше, / Христо́в бо крест на ра́мо взе́мше / і Того́ стопа́м усе́рдно послі́довавше, / на неви́димаго врага́ му́жеськи ополчи́стеся / і того́ ко́зні сокруши́сте, / моли́твами і слеза́ми, чистото́ю Бо́гові прибли́жившеся, / преподо́бнії отці́ на́ші Євфи́міє і Харито́не. / Я́ко со́лнце, осіява́єте світоза́рними луча́ми чуде́с ва́ших, / всіх нас спасі́те с ві́рою призива́ющих вас / і творя́щих честну́ю ва́шу па́м'ять, / і, я́ко іму́щії дерзнове́ніє ко Спа́су, // мир ми́рові іспросі́те і спасти́ся душа́м на́шим."],"h":"Євфимію й Харитону Сянжемським, глас 1"},{"ps":["Свята́я твоя́ па́м'ять / Су́ждальськую страну́ весели́ть, / ві́рния же вся созива́єть во всечестни́й храм твой, / іді́же ни́ні соверша́ється всесла́вная па́м'ять твоя́, / Євфроси́ніє преподо́бная, / моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."],"h":"Євфросинії Суздальській, глас 4"},{"ps":["Преподо́бне о́тче наш Єлиссе́є, / с Лавре́нтієм чу́дним подвиза́лся єси́, учи́телю своєму́ подража́я, / земну́ю сла́ву і честь стопа́м Христа́ пове́ргли єсте́, / ті́мже Госпо́дь увінча́ вас // нетлі́нним вінце́м сла́ви Своєя́."],"h":"Єлисею Лавришевському й свт. Лаврентію, затворнику Печерському, єпископу Туровському, у Ближніх печерах, глас 3"},{"ps":["Благолі́піє до́му Госпо́дня люб'я́, / расточи́л єси́ неща́дно імі́ніє твоє́ во украше́ніє того́, / преподо́бне Єра́зме, / тім ни́ні жив'я́ в дому́ Госпо́дні на Небесі́, // моли́ і нам освяти́тися в жили́ще Госпо́днє."],"h":"Еразму Печерському, у Ближніх печерах, глас 4"},{"ps":["Ду́хом горя́ путеше́ствія к святи́м місто́м, / стра́нствовал єси́ в Гре́чеськую зе́млю, / святи́телю Єфре́ме, / отню́дуже со мно́гою по́льзою возвраща́яся, / уста́в свята́го Студі́йськаго монастиря́ списа́в, / а́ки ні́кий многоче́стен дар, сі́мо прине́сл єси́, / і́мже і днесь Це́рков Россі́йськая управля́єма // сла́вить тебе́, і́стиннаго о ней проми́сленника."],"h":"Єфрему Печерському, єпископу Переяславському, глас 8"},{"ps":["Чи́стаго ра́ди і непоро́чнаго твоєго́ житія́, / Богоно́се о́тче Ігна́тіє, / приє́мий от Го́спода чудотво́рния да́ри ісціля́ти немощни́я, / ісціли́, мо́лим тя, і не́мощі на́ша, // моля́ о нас Єди́наго Человіколю́бця."],"h":"Ігнатію, архімандриту Печерському, у Дальніх печерах, глас 4"},{"ps":["Воі́стину досто́йні нарече́н бил єси́ Іларіо́н, / ти́хостен бо і кро́ток нрав по і́мені твоєму́ імі́л єси́, блаже́нне, / і́мже кро́ткому Го́споду Ісу́су благоугоди́в, // моли́ся Єму́ о нас рабі́х твої́х."],"h":"Іларіону, схимнику Печерському, у Дальніх печерах, глас 1"},{"ps":["От ю́ности сосу́д ізбра́нен бил єси́ / і в житії́ Бо́гу послужи́л єси́, / і́ноков наста́вниче Інноке́нтіє, / потща́лся єси́ ху́ждшеє покори́ти лу́чшему, / ті́мже і стра́сті умертви́в, / возви́сился єси́ к зрі́нію красоти́ несозда́нния, / в Бо́зі Єму́же предстої́ши, // моли́, о́тче, Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Інокентію Комельському, Вологодському, глас 4"},{"ps":["Я́ко Боже́ственную лі́ствицю, обріто́хом, Іоа́нне преподо́бне, / твоя́ Боже́ственния доброді́телі, / к Небесі́ возводя́щия ни: / доброді́телей бо ти бил єси́ воображе́ніє. // Тім моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."],"h":"Іоанну Лествичнику, глас 4"},{"ps":["Несумні́нно Христа́ іски́й, / Христо́во бога́тство прия́ти наді́явся, / зла́та грома́ду безнаде́жну сотво́р, / ско́ро прескочи́, я́ко я́же посреди́ Ла́заря і бога́таго про́пасть, / і легко́ воспря́ну во авраа́мськоє ні́дро, / пусти́нний Іоа́нне, тезоімені́те благода́ті і прозра́чному го́луби, / тім і от Бо́га приіми́й прозрі́нія дар / і честно́му Фео́дору єпи́скопу ізреки́й неви́денноє писа́ніє / і благочести́ву царю́ Моа́вію му́ченичеський по́двиг. / Ті́мже мо́лим тя, о́тче: // умоли́ Христа́ за ни, чту́щия тя."],"h":"Іоанну Печерніку (що в країнах Вавилонських), глас 2"},{"ps":["Я́ко зві́зди многосві́тлия, от ю́ности возсія́вше, / освіти́ли єсте́ сердца́ ві́рних пренесе́нієм честни́х моще́й ва́ших, / доброді́тельми чуде́с ва́ших, во пло́ті я́ко бо А́нгели на землі́, показа́стеся, / поще́нієм насажде́ні би́сте, я́ко дре́во при вода́х воздержа́нія, / напоє́ни струя́ми слез ва́ших, і скве́рну оми́сте, / сего́ ра́ди яви́стеся прия́телище Бо́жия Ду́ха, Іоа́нне і Ло́нгине, // молі́те Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Іоанну й Лонгину Яренгським, на перенесення мощей, глас 8"},{"ps":["Я́ко дре́во насажде́нно при вода́х воздержа́нія, / струя́ми слез твої́х напая́єм, / преподо́бне о́тче Іоаса́фе, / сі́яв бо слеза́ми, / в ра́дості жне́ши доброді́тельния рукоя́ті. / Тім Вели́кий Мздовоздая́тель в жи́тницях Небе́сних тя сокро́вище положи́, / но помина́й чту́щих любо́вію пресві́тлую па́м'ять твою́, / моли́ Святу́ю Тро́йцю, преподо́бне Іоаса́фе, // спасти́ся душа́м на́шим."],"h":"Іоасафу Каменському, Спасокубенському, Вологодському чудотворцю, глас 2"},{"ps":["Іспе́рва житіє́ твоє́, преподо́бне, / хи́тростію благоюро́дства от челові́к утає́но на Небесі́х пред А́нгели явле́нно бисть: / і а́ще на землі́ тьмо́ю оче́с претика́яся хожда́ше, / но ми́сленними кри́ли на висоту́ возше́д, / присносу́щним сві́том облиста́єм, / во Оте́чествії наслі́довал єси́; / і земни́х мня́щихся кра́сних хра́мов не тре́бовав, / но в Небе́сних се́ліх пресві́тлия оби́телі стяжа́л єси́; / ні ри́зами м'я́гкими оді́яся, / но па́че власяни́цю возлюби́в / і сего́ ра́ди па́че всіх імі́ній земни́х Небе́сная сокро́вища приобрі́л єси́; / і на землі́ пло́тян сий со безпло́тними совокупля́яся, / Небе́сній Цари́це служа́ і Той приноси́мих а́нгельських пі́сней наслади́лся єси́, / ї́хже мно́зі лю́діє, жела́юще, наслади́тися не мо́гуть. / Сего́ ра́ди Всеви́шній Творе́ць о́браз Свой / і Ро́ждшия Єго́ Богома́тере / с висоти́ возду́ха на ру́ці твоя́, / я́ко на херуви́мськая носи́ла дарова́ тебі́, / от него́же присносу́щним сві́том о́чі твої́ уясни́, / і, я́ко росоточа́щий о́блак моли́твами твої́ми весь мир ми́лованний напої́, / і ни́ні в послі́дняя времена́ святу́ю персть твою́, я́ко Єде́мський істо́чник во ісціле́ніє неду́гов устро́ї, / Єго́же моли́, наста́вниче наш, чудоно́сче Іо́сифе, // дарова́ти нам мир і ве́лію ми́лость."],"h":"Йосифу Заоникієвському, глас 4"},{"ps":["Безнача́льнаго о́наго і ти́хаго мі́ста, / іді́же ність печа́лі, ні воздиха́нія, / дости́гнути, преподо́бне, жела́я, / не дал єси́ себе́ зді поко́я нима́ло, / но при́сно день і нощ в ді́ліх вся́ких / і жесто́ком житі́ї трудолю́бно подвиза́яся, пребива́єши, / тім жела́ємого получи́л уже́, Іпа́тіє, // моли́ся о душа́х на́ших."],"h":"Іпатію цілителю, Печерському, у Дальніх печерах, глас 1"},{"ps":["Правосла́вія сла́дость, некта́р прему́дрости, о́тче преподо́бне, ізлія́л єси́ в сердця́ ві́рних я́ко бога́тство: житіє́м свої́м і уче́нієм показа́лся єси́ жива́я кни́га Ду́ха, Іусти́не Богому́дре, моли́ Христа́ Бо́га Ло́госа да оло́госить тя почита́ющих."],"h":"Іустину (Поповичу) Челійському, глас 8"},{"ps":["Я́ко вели́каго во отці́х Варлаа́ма учени́к, / прехва́льне Константи́не, / і сам ча́до послуша́нія, блаже́ннаго Косму́, возрасти́л єси́, / ті́мже, преподо́бнії, вку́пі Престо́лу Влади́чню ни́ні предстоя́щії, / моли́твами ва́шими во ві́рі Правосла́вній нас утверді́те, / в послуша́нії Це́ркві Святі́й укріпі́те // і вся поле́зная душа́м на́шим іспросі́те."],"h":"Костянтину й Косьмі Косинським, Старорусським, глас 3"},{"ps":["Новоявле́ннаго уго́дника Бо́жия почти́м, / Корни́лія преподо́бнаго, / крест на ра́мо взе́мшаго, / і́го Христо́во усе́рдно поне́сшаго, / і́же на неви́димия враги́ му́жественно подвиза́вся / і ко́зні їх попра́в, я́ко добр во́їн, // Влади́ці Христу́ предста́ і мо́литься о душа́х на́ших."],"h":"Корнилію Переяславському, глас 8"},{"ps":["Му́ченичеською кро́вію, свяще́нне Ку́кше, / в про́повіді Єва́нгелія со ученико́м ті блаже́нним Ни́коном, че́стне украси́вийся, / і Пи́мене, в по́стничестві світоза́рне просія́вий, / в єди́н день і час внидо́сте в світ незаходи́мий, / іді́же молі́теся Го́сподеві, // да пода́сть нам ве́лію ми́лость."],"h":"Кукші, священномученику, і Пимену посницю, Печерським, у Ближніх печерах, глас 3"},{"ps":["Затвори́вий себі́ Го́спода ра́ди в те́мній пеще́рі, / преподо́бне о́тче Лавре́нтіє, многолі́тні / і О́ному до́брі в ней угоди́вий, / пода́ждь і нам от вся́каго зла чу́вствія затвори́ти, / і тьми страсте́й отврати́тися, // і сві́тлость получи́ти Ца́рствія Небе́снаго."],"h":"Лаврентію, затворнику Печерському, у Дальніх печерах, глас 3"},{"ps":["От м'яте́жа мирська́го удали́вся, / к немерца́ющему Сві́ту прите́кл єси́, / преподо́бне о́тче Ло́нгине, / і ни́ні чи́сті зри́ши Святу́ю Тро́йцю, / Ю́же моли́ за ни недосто́йния, // да спасе́ть ду́ші на́ша."],"h":"Лонгину Коряжемському, глас 1"},{"ps":["Преподо́бне і Богоблаже́нне о́тче Ло́нгине, / врат монасти́рських опа́сний храни́телю, / опа́снейший же і неуси́пний свої́х чу́вствій / от вся́каго мирська́го су́єтствія затвори́телю, / моли́ наре́кшаго Себі́ двер Го́спода Сла́ви, // да отве́рзеть нам двер ми́лости Своєя́."],"h":"Лонгину, воротареві Печерському, у Дальніх печерах, глас 1"},{"ps":["От ю́ности Христа́ усе́рдні возлюби́в, / вда́лся єси́ Тому́ весь, я́ко непоро́чна же́ртва, / і, і́го Єго́ благо́є на себі́ взем, / рабо́тал в нем, всече́стне Мака́ріє, спі́шні, // ті́мже у́бо мо́лим тя: моли́ся о душа́х на́ших."],"h":"Макарію, дияконові Печерському, у Дальніх печерах, глас 7"},{"ps":["Жениха́ твоєго́ смерть ви́дівши, / разсмотре́ла єси́ тлі́нную жизнь і су́єтіє ми́ра, / отвсю́ду вину́ приї́мши, / Нетлі́нному Обру́чнику уневі́стилася єси́, / посто́м і смире́нієм любо́в Того́ постига́ющи. / Тім ни́ні ра́дується со А́нгели, // преподо́бная Макри́но, дух твой."],"h":"Макрині, глас 2"},{"ps":["Умертви́в плотські́я по́хоті мно́гим воздержа́нієм / і копа́нієм гробо́в святи́м, / при́сно, а́ки мертв, в пеще́рі жив'я́, / ме́ртвия повелі́нієм свої́м воздвиза́л єси́, / Ма́рко прехва́льне, / мертви́ і на́ша мудрова́нія плотська́я / і наста́ви нас на тече́ніє доброді́телей, // моля́ о нас Єди́наго Человіколю́бця."],"h":"Марку Гробокопателю, Печерському, у Ближніх печерах, глас 1"},{"ps":["Я́ко незаходи́моє со́лнце возсія́ нам днесь / світоза́рними твої́ми моли́твами, преподо́бне о́тче наш Ма́роне, / і́же ні́кия гори́ дости́гл / і та́мо на ней живу́щими нечести́вими чтом бисть, / за превосходя́щую твою́ к Бо́гу доброді́тель, / і та́мо обрі́т тре́бище і́дольськоє. Бо́гу освяти́в, в нем пребива́л єси́, / і ви́дів Человіколю́бець Бог твой по́двиг і труди́, / дарова́ тебі́ дар Свой, / і́мже пронесе́ся і́м'я твоє́ в челові́ціх, / ціли́ти ско́рби, огне́вицю і тряса́вицю прибега́ющим к тебі́ с ві́рою. / Ті́мже і зове́м ті: / ра́дуйся, ціли́телю наш ско́рий; / ра́дуйся, засту́пниче наш те́плий, / предстої́ши бо у Пресвяти́я Тро́йці, / моли́ся Той о призива́ющих і́м'я твоє́ свято́є, // да ізба́вить от сих тя́жких скорбе́й і спасе́ть ду́ші на́ша."],"h":"Мароні, пустельникові Сирійському, глас 8"},{"ps":["Тя́жким неду́гом стра́ждущий і людьми́ заби́тий, / моли́л єси́ жа́жду утоли́ти, преподо́бне Марти́не, / ті́мже Христо́с посла́ с Небесе́ благові́рних Бори́са і Глі́ба // тебі́ послужи́ти і неду́г ісціли́ти."],"h":"Мартину Туровському, глас 1"},{"ps":["Бо́гу от ю́ности, о́тче, ізбра́вшу і возлюби́вшу тя / і прови́дящу твоє́ до́броє проізволе́ніє, / наставля́єть тя прийти́ к преподо́бному Своєму́ уго́днику / Кири́ллу всеблаже́нному, / от него́же наста́влен бисть на путь спасе́нія, / стра́хом Бо́жиїм, і чистото́ю душе́вною, і благогові́нієм, / і непреста́нними к Бо́гу моли́твами / во мно́зі по́двизі жизнь свою́ препроводи́л єси́ / і за́повіді Бо́жия непоро́чно соблю́л єси́, / па́стир і наста́вник і́ноком преди́вен бил єси́, / і ни́ні Престо́лу Христо́ву со дерзнове́нієм предстої́ши на Небесі́х, / со А́нгели светлоликовству́я, / о́тче преподо́бне, Мартинія́не всеблаже́нне, / не преста́й моли́ся Христу́ Бо́гу // спасти́ і поми́ловати ду́ші на́ша."],"h":"Мартініану Білозерському, глас 2"},{"ps":["Служи́вий в чи́ну дия́конства Го́сподеві до́брі, / честни́й ієродия́коне Марти́ріє, / і та́мо я́ко слуга́ Госпо́день обріти́йся, / іді́же і Госпо́дь твой, / моли́ся Єму́ і о нас, // да пода́сть нам ве́лію ми́лость."],"h":"Мартирію, дияконові Печерському, у Дальніх печерах, глас 1"},{"ps":["Житіє́м чи́стим і любо́вію, я́же ко Пречи́стій Бо́жієй Ма́тері, / стяжа́ла єси́ дар чадоро́дія пресла́вний, / світи́льника ми́ру, ди́внаго Симео́на, / тім тя, Ма́рфо, // я́ко ма́тер, о ча́ді веселя́щуюся, пі́сньми ублажа́єм."],"h":"Марті Антіохійській, Едеській, глас 4"},{"ps":["Мужескому́дрено утаї́вшися вра́жиїх лука́вих путе́й, Матро́но, / к жи́зні воі́стину ше́ствовавши несумні́нною во́лею / і неукло́нноє тече́ніє Богому́дро сконча́вши, / от Христа́ прия́ла єси́ благода́ть духо́вную, / тім і во́ду цільба́м істоча́єши / любо́вію притека́ющим в па́м'ять твою́ сла́вную, / мни́хом похвала́, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Матроні Константинопольській, глас 8"},{"ps":["Присносу́щния, блаже́нне, жела́я сподо́битися жи́зні, / пра́ведні і непоро́чні / жизнь свою́ препроводи́л єси́ в ни́нішнем ві́ці, / ті́мже, Мерку́ріє, жела́ємаго ти дости́г, // моли́ і нам ві́чния сподо́битися жи́зні."],"h":"Меркурію Печерському, у Дальніх печерах, глас 5"},{"ps":["Крила́ми ми́сленними к Богові́дінію возлеті́в разу́мно, / м'яте́ж ми́ра оста́вил єси́, блаже́нне, / презрі́в пло́ті мудрова́нія, / му́дрость Ви́шнюю взиска́л єси́, є́же жи́ти с Бо́гом, / і всім о́браз дав собо́ю, глаго́ля: // добро́ єсть с Бо́гом жи́ти, Михаї́ле преподо́бне."],"h":"Михаїлу Малеїну, глас 8"},{"ps":["Чист і прав сий се́рдцем, / і свят, преподо́бне Не́сторе, душе́ю, / прост же па́ки і не умі́я сам чести́ книг, / сего́ ра́ди чту́щим я прилі́жні внима́л єси́, / і, о́ная в себі́ соблюда́я, спі́шно тща́лся єси́ ісправля́ти, // я́же я́ко разу́мен іспо́лнив, обрі́л єси́ Ца́рствіє Небе́сноє."],"h":"Несторові Некнижному, Печерському, у Дальніх печерах, глас 2"},{"ps":["Світи́ло незаходи́маго сві́та / страні́ на́шей яви́лся єси́, богоблаже́нне, / до́блественне претерпі́во вра́жия озлобле́нія, / біє́ніє і ра́ни я́ко оде́жда нетлі́нія вміни́шася тебі́, / со звірми́ бо бра́вся, / і от челові́к злих прободе́нія прия́в, / о тіх моли́лся єси́: / не поста́ви їм гріха́ сего́, глаго́ля; / ті́мже Влади́ці Христу́ уподо́бился єси́, / достохва́льне Ника́ндре, о́тче наш, // моли́ся о душа́х на́ших."],"h":"Никандру пустельникові Псковському, чудотворцю, глас 6"},{"ps":["Послу́шаша Госпо́дня гла́са, / до́брії рачи́тели би́вше, / благи́й Єго́ яре́м на ся взе́мше, / усе́рдно понесо́сте / і по́стничества путь дости́гше, / преподо́бнії отці́, святі́ї чудотво́рці, / во́їни Небе́снаго Царя́ Христа́, / Ники́то, Кири́лле, Ники́форе, Кли́менте і Ісаа́кіє, / сего́ ра́ди от Вседержи́тельния десни́ці / вінці́ неув'яда́ємими ув'язо́стеся, і Небе́сною сла́вою оді́ястеся, / і чудотворе́нії обогати́стеся, / ті́мже і о нас моли́ти не преста́йте, / да полу́чим ві́чних благ, / ми же си́це взива́єм: / сла́ва Да́вшему вам к по́двигу крі́пость, / сла́ва Вінча́вшему вас, // сла́ва Даю́щему ва́ми всім ісціле́нія."],"h":"Никиті, Кирилу, Никифору, Клименту й Ісаакію, братам Алфановим (Сокольницьким) у Новгороді, глас 1"},{"ps":["От Ца́рствующаго гра́да пресе́льник яви́ся / і я́же в нем вели́кия оби́телі / і, промишле́нієм Боже́ственнаго ра́зума окормля́єм, / к морськи́м страна́м устреми́ся, / всели́ся же в пусти́ню, уклоня́яся мирськи́я молви́, / і си́лою Свята́го Ду́ха вооружи́лся єси́, / кре́стним ору́жієм враги́ своя́ прогоня́я, / посто́м і непреста́нною моли́твою жизнь свою́ соверша́я, / сревну́я вели́ким отце́м Анто́нію, і Ону́фрію, і Па́влу Фиве́йському, / с ни́миже Го́сподеві моли́ся, о́тче Никоди́ме, // спасти́ся душа́м на́шим."],"h":"Никодиму Кожеозерському, глас 8"},{"ps":["Христо́ва виногра́да лоза́ яви́лся єси́, Богоблаже́нне Ни́коне, / гро́здіє принося́ Єму́ — доброді́телі твоя́, / і про́чіїх, к ті́мже наставля́я, / приводи́л єси́ Христу́ Бо́гу, // Єму́же, мо́лим тя, моли́ся за ду́ші на́ша."],"h":"Никону, ігумену Києво-Печерському, у Ближніх печерах, глас 5"},{"ps":["Кири́лла равноапо́стольнаго язи́к, / защити́в, обнови́л єси́ / і Патріа́рха Євфи́мія благослове́ніє Тро́їчеськоє, преднача́в, / іспо́лнил єси́. / Твої́м бо трудо́м болга́ром / па́ки вня́тним їх язи́ком благоче́стіє воспропове́дася, / і тобо́ю пе́рвіє нача́ть Про́мисл Тро́їчеський - / ді́ло освобожде́нія ро́да Болга́рськаго. / Сего́ ра́ди тя почита́єм, / Паї́сіє блаже́нне, // і любо́вію соверша́єм честну́ю па́м'ять твою́."],"h":"Паїсію Хіландарському (болгарський), глас 4"},{"ps":["В пусти́ні живи́й в то́лстинних і многошве́нних твої́х ри́зах, / і без тщесла́вія і м'яте́жа внутр поя́ Бо́гові, / і челові́ча дія́нія собо́ю прообразова́во в наказа́ніє, о́тче Па́мво, / моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."],"h":"Памві, пустельникові Нітрійському, глас 5"},{"ps":["Пусти́нноє і безмо́лвноє житіє́ возлюби́вши, / і во слід Христа́, Жениха́ твоєго́, усе́рдно поте́кши, / і Того́ благо́є і́го во ю́ности твоє́й взе́мши, / Кре́стним зна́менієм к ми́сленним враго́м му́жеськи вооружи́вшися, / по́стничеськими по́двиги, посто́м, і моли́твами, і сле́зними ка́плями / у́гліє страсте́й угаси́ла єси́, достосла́вная Параске́во: / і ни́ні в Небе́снім черто́зі / с му́дрими ді́вами предстоя́щи Христу́, // моли́ о нас почита́ющих честну́ю па́м'ять твою́."],"h":"Параскеві Сербській, глас 4"},{"ps":["Жите́йських молв, преподо́бне, отве́ргся / і, я́ко птищ, обрі́те себі́ в пусти́ні безмо́лвіє, / в моли́твах і бді́нії приліжа́ Бо́гові, / преподо́бне о́тче Пахо́міє, / і оста́ви дре́внєє пребива́ніє, / і оти́де в пусти́ню, і в ней водвори́ся, / і соста́ви оби́тель во і́м'я Пресвяти́я Тро́йці, / і процві́л єси́, а́ки фи́никс, / і бисть о́браз утіше́нія духо́внаго. / Ті́мже, преподо́бне Пахо́міє, // моли́ Пресвяту́ю Тро́йцю спасти́ся душа́м на́шим."],"h":"Пахомію Нерехтському, глас 1"},{"ps":["Любо́вію Христо́вою просвіще́н, / ізмла́да возлюби́л єси́ мона́шеськоє житіє́ / і, возненави́дів вся́коє плотсько́є наслажде́ніє, / житіє́ твоє́ іспо́лнил єси́ терпі́нієм, посто́м і моли́твами, / просія́л бо єси́ доброді́тельми, я́ко сві́тлоє світи́ло, / і ни́ні, усе́рдно мо́лим тя: / моли́ Христа́ Бо́га / сохрани́ти оте́чество на́ше і весь крестоно́сний наро́д се́рбський // і всім дарова́ти ве́лію ми́лость."],"h":"Петру Коришському, Сербському, глас 4"},{"ps":["Богоно́снаго Анто́нія смиренному́дрієм подража́я, / терпі́нієм І́ову подо́б'яся, / не ісціле́нія от болі́зні, но па́че протяже́нія тоя́ / жела́л єси́ себе́, терпіливоду́шне Пи́мене, / да не ка́ко, здрав бив / і от мі́ста сего́ роди́тельми істо́ржен, / сожи́тія преподо́бних і чи́на їх лиши́шися, / тім па́че наде́жди от сами́х А́нгел постриже́н бил єси́, / с ни́миже моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Пимену Многохворому, Печерському, у Ближніх печерах, глас 5"},{"ps":["Затвори́вийся в мі́сті те́мні, Богоблаже́нне Піо́ре, / і отню́д сві́та сего́ і вся́ких пре́лестей в нем су́щих зрі́ти нехоте́вий, / Сві́та же днесь Невече́рняго сподо́блься, // моли́ і нам Сві́том ті́мже озари́тися."],"h":"Піору, затворнику Печерському, у Дальніх печерах, глас 5"},{"ps":["Тезоімени́т зва́нію твоєму́, / я́ко многопло́дноє дре́во, / насажде́н сий во оби́телі Бо́жия Ма́тере, / мно́гая і чу́дная тща́нієм твої́м ісправле́нія показа́вий, / му́дре Поліка́рпе, / моли́ Христа́ Бо́га о нас, // я́ко да і ми, мно́гія плоди́ доброді́телей Єму́ прине́сше, спасе́мся."],"h":"Полікарпу, архімандриту Печерському, у Ближніх печерах, глас 4"},{"ps":["Преподо́бне і чудотво́рче, о́тче Про́хоре, / препита́вий во гла́ді а́лчущия хлі́бом от би́лія і со́лію от пе́пела, / напита́й і нас пи́щею духо́вною, / моля́ Христа́ Бо́га // о душа́х на́ших."],"h":"Прохору Печерському, у Ближніх печерах, глас 4"},{"ps":["От ю́ности горя́чим жела́нієм Боже́ственния любве́ разжига́єм, / жите́йськія молви́ оста́вль, преподо́бне, / учени́к вели́каго Се́ргия бил єси́, / безмо́лвієм і жесто́ким пребива́нієм, / бді́нієм і моли́твою, посто́м послі́дуя Христу́; / сего́ ра́ди ізбра́нієм учи́теля твоєго́, свяще́нства сподобля́єшися / от руки́ блаже́ннаго Алексі́я / і па́стир поставля́єшися оби́телі, я́же на Киржачеі, / в ней же трудолю́бно пожи́в, ко Го́споду отхо́диши, / Рома́не преподо́бне, / моли́ о нас Христа́ Бо́га, / со учи́телем твої́м преподо́бним Се́ргиєм, // спасти́ся душа́м на́шим."],"h":"Роману Киржацькому, глас 4"},{"ps":["Я́ко трисві́тлаго со́лнця світоза́рния зві́зди, / Тро́їчеським сві́том озаря́єте сердца́ ві́рних, / сосу́ди Сві́та Пресвяти́я Тро́йці я́вльшеся, / і преди́вним ва́шим житіє́м і́ноком би́сте тве́рдії законоположи́теліє / і це́рквам благолі́піє, і благові́рним, і святи́телем, і всім лю́дем, / вся бо де́монськия скве́рни отгна́вше отсю́ду / ва́шими чи́стими уче́нії і ді́ли, / до́брі упасо́сте ста́до, со́бранноє ва́ми, / но і ни́ні мо́лим вас: / посіща́йте чад свої́х, я́ко іму́щиє дерзнове́ніє ко Святі́й Тро́йці, / Богому́дре, Се́ргіє с чу́дним ученико́м свої́м Ни́коном, // і молі́те Христа́ Бо́га да спасе́ть ду́ші на́ша."],"h":"Сергію й Никону Радонезьким, глас 8"},{"ps":["Ра́дуйся, пусти́не Ра́донежськая, / ізрасти́вшая крин духо́вний, / во вертогра́ді преподо́бнаго Се́ргия: / Си́мона, архімандрі́та Смоле́нськаго, / позна́вшаго сві́тлость послуша́нія / і ди́внаго птиць виді́нія сподо́бившагося, // сего́ воспомина́юще, Бо́га прославля́єм."],"h":"Симону Радонезькому, глас 5"},{"ps":["Простра́нна путі́, веду́ща в па́губу, / блаже́нне Софро́ніє, угонза́я, / затвори́лся єси́ в те́мні мі́сті пеще́рнім, / іді́же день і нощ в моли́твах і слеза́х / і в ручно́м ді́лі подвиза́яся, // обрі́л єси́ ві́чний живо́т і наслажде́ніє."],"h":"Софронію, затворнику Печерському, у Дальніх печерах, глас 1"},{"ps":["Хліби́ прино́сния рука́ми свої́ми творя́, / псалмопі́ніє непреста́нноє усти́ свої́ми / я́ко же́ртву хвали́ приноша́ше Го́сподеві, / со честни́м Никоди́мом, блаже́нне Спиридо́не, // с ни́мже моли́ся Христу́ Бо́гу о душа́х на́ших."],"h":"Спиридону й Никодиму, просфорникам Печерським, у Ближніх печерах, глас 4"},{"ps":["Уче́нію повину́яся Богоно́снаго Феодо́сія, / поста́влен бисть от него́ вождь би́ти свято́му єго́ ста́ду, / є́же до́брі паси́й, / це́рков Богоро́диці, во́лею Тоя́ осно́ванную чу́дне, / соверши́л єси́ благолі́пно, / приснопа́м'ятне Стефа́не, // в не́йже нам, моля́щимся, іспроси́ от Христа́ Бо́га ве́лію ми́лость."],"h":"Стефану, ігумену Печерському, єпископу Володимир-Волинському, глас 8"},{"ps":["Воздержа́нієм житіє́ украси́ і стра́сті умертви́в, / посрами́л єси́ вра́жия прило́ги, о́тче Стефа́не, / і преложи́ся к Бо́гу, чудотво́рець показа́ся, / во ві́чній сла́ві со А́нгели лику́я, // с ни́ми же моли́ поми́ловати ду́ші на́ша."],"h":"Стефану Савваїту, глас 5"},{"ps":["Оби́телі Хиланда́рськия свяще́нних строї́телей / і Афо́на світи́льники, Се́рбії похвалу́, / Симео́на велича́йшаго, преподо́бних лі́поту, / і род єго́ чу́дний, святи́теля, — глаго́лю, — Са́вву, / прийді́те согла́сно почти́м, глаго́ля: / молі́те Христа́ Бо́га / о па́стві ва́шей, блаже́ннії, // і о є́же Це́ркві свобо́дней би́ти от обстоя́ній."],"h":"Стефану, в чернецтві Симеону, цареві Сербському, Мироточивому, і святителю Саві I, архієпископу Сербському, глас 1"},{"ps":["Братолю́бні тя живу́ща ви́дів любве́ ненави́стник, / побіди́л тя во гнів, / но, ві́дий твоя́ пре́жнія труди́ любве́ істо́чник — Госпо́дь, / преложи́ тя па́ки на братолю́біє, / в не́мже ти про́чеє пожи́в Богоуго́дні, // моли́ся о нас, я́ко да поживе́м братолю́бні."],"h":"Титу, пресвітеру Печерському, у Ближніх печерах, глас 1"},{"ps":["Во́їнство тлі́нноє оста́вль, / в нетлі́нном ввоєни́лся єси́ Христо́ві, / і ору́жієм Єго́ кре́стним побіди́в подзе́мних єфіо́пов, / побі́ди віне́ць от Христа́, Ти́те, сла́вно прия́л єси́, // Єму́же моли́ся дарова́ти нам мир і ве́лію ми́лость."],"h":"Титу Печерському, колишньому воїну, у Дальніх печерах, глас 3"},{"ps":["Путі́, вводя́щаго в жизнь, наста́вник і учи́тель бил єси́: / пе́рвіє бо, преподо́бне о́тче наш Три́фоне, / прише́л єси́ в часть Норве́гськия землі́ / і в послі́дніх конці́х сі́верния страни́ язи́ки просвіти́л єси́, / породи́во водо́ю і Ду́хом Святи́м, / і свяще́нная твоя́ ча́да в безпло́дней пусти́ні, / я́ко древа́ ма́сличная, насади́л єси́, / ве́лію оби́тель Святи́я і Живонача́льния, Єдиносу́щния і Неразді́льния Тро́йці созда́л єси́ / і мона́хов мно́жество собра́в. / Тім, я́ко апо́столом і пустинножи́телем равноче́стна чту́ще тя, / приле́жно припа́дающе, вопіє́м: / моли́ всіх Бо́га за Ру́ськую зе́млю, за о́бласть твою́ і за вся лю́ди, // почита́ющия па́м'ять твою́."],"h":"Трифону Печенгському, Кольському, глас 8"},{"ps":["Позна́н бив от пеле́н освяще́н / і я́влься благода́тей іспо́лнен, / чудеси́ мир озари́л єси́ / і де́монов мно́жество отгна́л єси́, / священноді́телю Фео́доре, // ті́мже о нас моли́ся Го́сподеві."],"h":"Феодору Сікеоту, єпископу Анастасіупольському, глас 2"},{"ps":["Пре́жде запе́нся бога́тственною сі́тію, я́ко челові́к, / но посліди́ нището́ю нестяжа́нія посрами́л єси́ врага́ / і моли́твами твої́ми, честни́й Феодо́сіє, / прия́т от Бо́га прозрі́нія дар. / Тім і честно́му єпи́скопу Фео́дору прорече́ о Святі́й Це́ркві, / є́же на враги́ одолі́ніє, // і ни́ні моли́ся Христо́ві за чту́щих тя."],"h":"Феодосію Едеському, стовпнику, глас 3"},{"ps":["В блаже́ннім безмо́лвії пусти́ннім / і на собо́ріх, любо́вію к Бо́гу горя́, / посрами́л єси́ лука́вих бісо́в і єрети́к злочести́вих. / На моли́тві же стоя́, огня́ сві́тлостію просія́л єси́ / і преставле́нієм твої́м А́нгелов пою́щих обвесели́л єси́, / Феодо́сіє, о́тче наш, / сего́ ра́ди мо́лим тя: // моли́ся о душа́х на́ших."],"h":"Феодосію Терновському, глас 3"},{"ps":["Боже́ственнаго стра́ха огне́м ду́шу свою́ распали́л єси́, / очи́стився покая́нієм і украси́вся кро́тостію і смире́нієм, / восте́кл єси́ к невече́рнему Сві́ту — Христу́, / преподо́бне о́тче Феокти́сте, / і ни́ні, трисо́лнечним сві́том озаря́єм, / на Небесі́ лику́єши, // моли́ о нас, ві́рою почита́ющих честну́ю па́м'ять твою́."],"h":"Феоктисту, колишньому Драгутину, королю Сербському, глас 4"},{"ps":["Воздержа́нієм житіє́ укра́сил / і, у́ди умертви́в, / побіди́л єси́ вра́жия ко́зні, о́тче Феофа́не, / преста́вился єси́ к Бо́гу во ві́чную жизнь, / я́ко досто́їн прича́стник, / моля́ся непреста́нно // поми́ловати ду́ші на́ша."],"h":"Феофану сповіднику, Сигріанському, глас 5"},{"ps":["Тая́ся, пожи́л єси́, прехва́льне, / но Христо́с тя показа́, / я́ко світи́ло на сві́щниці ми́сленнім, / і скрижа́ли ті вручи́ уче́ній духо́вних, / і́миже, святи́телю Феофила́кте, // і нас озари́."],"h":"Феофілакту сповіднику, єпископу Нікомидійському, глас 6"},{"ps":["Я́ко кедр, в пусти́ні дави́дськи расту́щ, і я́ко фі́нікс, благоуха́нен цвіту́щ, / ревни́тель учи́телю твоєму́ бил єси́, преподо́бному отцю́ Корни́лію, / стопа́м бо єго́ послі́довал єси́ / і, свято́є і́го взем, / сві́тлим житіє́м просія́л єси́, я́ко со́лнце, / я́влься ми́рові мно́гими чудеси́, о́тче Фили́ппе! / І ни́ні на Небесі́х предстої́ши Престо́лу Пресвяти́я Тро́йці / і, я́ко вели́коє імі́я дерзнове́ніє, / преподо́бнії свої́ ру́ці возді́в, // моли́ от враг сохрани́тися градо́м на́шим і спасти́ся душа́м на́шим."],"h":"Пилипу Ірапському, глас 4"},{"ps":["Світи́ла богосія́нная ми́ру / і і́ноков одушевле́нния зари́, / Фома́ чудеси́, Ака́кий же послуша́нієм, / возсія́сте сві́тло; / сих, я́ко іму́щих дерзнове́ніє к Бо́гу, / моли́твами во бра́ніх посо́бствовати мо́лим, / да про́сять от Христа́ Бо́га дарова́ти проще́ніє согріше́ній // чту́щим їх святу́ю па́м'ять."],"h":"Фомі Малеїну й Акакію Синайському, глас 1"}],"notes":[]},{"u":"Тропарі мученикам","e":"Troparia of the martyrs","secs":[{"ps":["Днесь блажа́ть тя ми́ра конці́, / Боже́ственних чуде́с іспо́лншеся, / і земля́ ра́дується, напи́вшися кро́ве твоєя́. / Христоимени́тії же лю́діє гра́да Ки́єва / освяще́нієм Боже́ственнаго хра́ма твоєго́ ра́достію возвесели́шася, / страстоте́рпче Гео́ргіє, / сосу́де ізбра́нний Свята́го Ду́ха, уго́дниче Христо́в. / Єго́же моли́ / с ві́рою і мольбо́ю приходя́щим во святи́й твой храм / да́ти очище́ніє гріхо́в, // умири́ти мир і спасти́ ду́ші на́ша."],"h":"Георгію Побідоносцю, глас 4"},{"ps":["Заре́ю Ду́ха обогати́вся, сла́вне, / і отту́ду восприї́м дерзнове́ніє, / іспові́дал єси́ на суди́щі му́жеськи Тро́йцю Єдиносу́щную, / ті́мже і ка́менієм побива́єм, / не покори́лся єси́. / Огне́м же сожига́єм, / обличи́л єси́ пре́лесть безбо́жних, / многострада́льне свя́те Нико́лає. / Сего́ ра́ди мо́лим тя: / іспроси́ душа́м на́шим // ве́лію ми́лость."],"h":"Миколаю Софійському, глас 3"},{"ps":["Свяще́нний Бо́гу Афиноге́н, в же́ртві служи́тель, / свяще́нноє учени́к свої́х принесе́ Христу́ заколе́ніє, / па́стир со слове́сними о́вцями і́де в Небе́сную огра́ду, / побіди́в свере́пеющия неві́рієм язи́ки. / Му́ченик Твої́х моли́твами, Христе́ Бо́же, // спаси́ ста́до Твоє́ от волко́в, губ'я́щих є."],"h":"Афіногену, єпископу, і десяти учням його, глас 8"},{"ps":["Бла́гости научи́вся, і трезвя́ся во всіх, / благо́ю со́вістію священнолі́пно обо́лкся, / поче́рпл єси́ от сосу́да ізбра́ннаго неізрече́нная, / і ві́ру соблю́д, ра́вноє тече́ніє соверши́л єси́, / священному́чениче Діоні́сіє, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."],"h":"Діонісію Ареопагіту, єпископу Афінському, глас 4"},{"ps":["Нищелю́бієм обогати́вся / і ми́лость воздержа́нія істочи́в, / наслажде́нія Ца́рствія Небе́снаго сподо́бися, / страда́льчеськи бі́ди приї́м по ста́ді своє́м, / і апо́столом обрі́теся ссе́льник, / о́тче священному́чениче Дорофе́є, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Доротею, єпископу Тирському, глас 5"},{"ps":["Преподо́бно житіє́ твоє́ проше́д, му́дре, / сві́тлим украси́лся єси́ хито́ном свяще́нства. / Пролива́я же кров му́ченичества, Єра́зме, / сподо́бился єси́ сви́ше мздов неле́стних / і, предстоя́ Тро́йці, мо́лишися о нас, воспіва́ющих тя."],"h":"Еразму Охридському, глас 4"},{"ps":["Тро́йці провозві́стници, / тро́йце му́чеников честна́я, / і́дольськоє нече́стіє обличи́вшії / і тьмочи́сленнаго врага́ сокруши́вшії, / ни́ні, со Христо́м ца́рствующе, молі́те, / свяще́нний Ермола́є со Ерми́ппом і Ермокра́том сла́вним, / я́ко да і на́ша враги́ побіди́м / і при́ймем от Царя́ всіх, Бо́га, ві́чний живо́т // і віне́ць нетлі́нний."],"h":"Єрмолаю, Єрмиппу й Єрмократу, священикам Нікомидійським, глас 8"},{"ps":["Апо́стольських нра́вов подража́телю / і престо́ла їх сонаслі́дниче, / архієре́єв удобре́ніє і му́чеников сла́во, Богодухнове́нне, / на огнь, і меч, і зві́ри дерзну́л єси́, ві́ри ра́ди / і, сло́во і́стини ісправля́я, / до кро́ве пострада́л єси́, / священному́чениче Ігна́тіє, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Ігнатію Богоносцю, глас 4"},{"ps":["Бла́гости научи́вся і трезвя́ся во всіх / благо́ю со́вістію священнолі́пно обо́лкся, / поче́рпл єси́ от сосу́да ізбра́ннаго неізрече́нная / і, ві́ру соблю́д, ра́вноє тече́ніє соверши́л єси́, / священному́чениче Ієрофе́є. // Моли́ Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Єрофею, єпископу Афінському, глас 4"},{"ps":["Жизнь твою́ цілому́дренно соверши́л єси́, нічто́же на землі́ па́че Христа́ предпоче́т, ра́дуяся, вшел єси́ на му́ченичеськоє благосла́віє, проти́в'яся мучи́теля повелі́нію, яви́лся єси́ вінцено́сець свяще́нний, і́бо Христо́с возме́здіє тебі́ дарова́ і всели́ тя в Ца́рство Небе́сноє."],"h":"Іринею Сремському, глас 8"},{"ps":["Страстоте́рпці Госпо́дні блаже́ннії, / Правосла́вную ві́ру Христо́ву со дерзнове́нієм пропові́дасте, / і на суди́щі уче́нія враго́в непра́вая обличи́сте, / того́ ра́ди і вве́ржені би́сте, святі́ї, / во глубину́ рі́чную, / ду́ші же ва́ші всели́шася в Небе́сния кро́ви, / іді́же со святи́ми предстоя́ще Престо́лу Царя́ всіх Бо́га, / молі́теся Єму́ за вся правосла́вния лю́ди, // по́двиги ва́ша че́стно почита́ющия."],"h":"Ісидору, пресвітеру, й тим, що з ним, 72-м, у Юр’єві Лівонському постраждалим, глас 2"},{"ps":["Лоза́ преподо́бства і стебль страда́льчества, / цвіт свяще́ннійший і плод Богода́нний, / ві́рним, всесвяще́нне, присноцвіту́щ, дарова́лся єси́, / но я́ко му́чеников сострада́лець / і священнонача́льников сопресто́льник, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Клименту, єпископу Анкірському, глас 4"},{"ps":["Боже́ственния Безкро́вния соверша́я Же́ртви, / кров твою́, от безбо́жних ага́рян ізлія́нную, / в же́ртву непоро́чную прине́сл єси́ Влади́ці твоєму́, Пастиренача́льнику Христу́. / Єго́же моли́, мо́лим тя, / проли́ти гнів на язи́ки, хотя́щия бра́ней; / христолюби́воє во́їнство на́ше на враги́ укріпи́ / і ста́до твоє́ от вся́ких бід неврежде́нно соблюди́, / тебі́ бо крі́пкаго засту́пника почита́єм, / но́вий свяшенному́чениче россі́йський, // святи́телю блаже́нний Мака́ріє."],"h":"Макарію, митрополиту Київському, глас 8"},{"ps":["По́стничеськи подвиза́вся і плоть покори́в ду́ху, вшел єси́ в тишину́ безстра́стія, ієре́йством же укра́шен, за Христа́ пострада́л єси́ тверді́йши, Єму́же моли́ся о чту́щих тя, священному́чениче Ники́то приснопа́м'ятне."],"h":"Никиті Слов’янину, глас 4"},{"ps":["Я́ко стріла́ огнезра́чная, / от Верхо́внаго по́слан бил єси́ Тавромені́йському престо́лу / уязвля́ти безбо́жних злоче́стіє, / ві́рних же сердца́ просвіща́ти, / я́же боговіща́нними твої́ми словеси́ во ві́рі утверди́в / і тече́ніє соверши́в, пострада́л єси́ до кро́ве, / священному́чениче Панкра́тіє, // моли́ за вся, пою́щия па́м'ять твою́."],"h":"Панкратію, єпископу Тавроменійському, глас 8"},{"ps":["От ви́шняго суда́ Христо́ва предста́тельствова ста́ду, / на па́житіх благожи́зненних упа́сл єси́ всему́дрими твої́ми догма́ти, / отгна́в А́рія, я́ко во́лка некро́ткаго, / вше́дшаго в них безбо́жними уче́нії. / Ті́мже і ду́шу твою́ положи́л єси́ за них, / па́стир наре́клся єси́, я́ко рече́ Госпо́дь, / ієра́рше Пе́тре блаже́нне, / моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти // чту́щим любо́вію ствяту́ю па́м'ять твою́."],"h":"Петру, архієпископу Олександрійському, глас 8"},{"ps":["Бо́жиїм смотре́нієм к святи́тельському служе́нію / святи́м Патріа́рхом Ти́хоном призва́нний, / ста́ду Христо́ву яви́лся єси́ страж неуси́пний / і защи́тник небоя́зненний, / священному́чениче Пе́тре. / Жесто́кая заточе́нія і да́льная ізгна́нія, / страда́нія і смерть от богобо́рцев претерпі́л єси́. / Віне́ць му́ченичеський прия́в, / на Небесі́ ни́ні ра́дуєшися. / Моли́ ми́лостиваго Бо́га, / да сохрани́ть Це́рков на́шу от нестроє́ній, / єдиноми́сліє і мир лю́дем Свої́м да́руєть // і спасе́ть ду́ші на́ша."],"h":"Петру (Полянському), митрополиту Крутицькому, глас 2"},{"ps":["Хвала́ Бо́гу і же́ртва жива́я / житіє́ твоє́, священному́чениче Фадде́є, яви́ся. / Посто́м, бді́нієм і моли́твою Небе́сная дарова́нія приї́м, / мно́гим до́брий помо́щник і уті́шитель бисть. / Па́стирською му́дростію і ти́хостію нра́ва укра́шен, / лука́вства враго́в Христо́вих препобіди́л єси́. / Сла́ва Да́вшему тебі́ во страда́ніїх крі́пость, / сла́ва, я́ко му́ченика, Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."],"h":"Фаддею (Успенському), архієпископу Тверському, глас 1"},{"ps":["Во́їни Христолюби́вії, страда́льці послуша́нія прехва́льнії, / Алекса́ндре ди́вний Пересве́те і Андре́є Осля́бей імену́ємий, / Се́ргия ігу́мена благода́тниє наслі́дници, / Кулико́вськия бра́ні ра́тници духо́внії, / ви бо змі́я ага́рянськаго побіди́сте. / Но і нас свої́м заступле́нієм не оста́висте, / тела́ми в хра́мі Рождества́ Богоро́диці почива́єте, / душе́ю в преви́шнем селе́нії пребива́єте. / Моли́те за весь род ру́ський правосла́вний, // преподо́бнії сро́дниці на́ші."],"h":"Олександру (Пересвіту) й Андрію (Ослябі), Радонезьким, глас 1"},{"ps":["Плотсько́є, я́ко безпло́тний А́нгел, возненави́дівши препита́ніє, / духо́вную во і́ночеськом чи́ну возлюби́л єси́ пи́щу, / і в нем Богови́дцю на Сина́ї Моїсе́ю / до́брим житія́ твоєго́ по́двигом уподобля́яйся, / мно́гими на горі́ Бо́жієй Пече́рськой возви́сился єси́ доброді́тельми, / іді́же в моле́нії к Ви́шннему непреста́нно пребива́л єси́, / ни́ні же со отці́ преподо́бними Пече́рськими, / а́ки би́сер многоці́нен, мощми́ нетлі́нними / в пеще́рі твої́ми пресві́тло сія́єши, / а душе́ю со А́нгели пред Престо́лом Бо́жиїм, / святи́й преподобному́чениче Анаста́сіє, предстої́ши, / о нас всегда́ моля́ся ко Го́споду // спасти́ся душа́м на́шим."],"h":"Анастасію, дияконові Печерському, у Ближніх печерах, глас 4"},{"ps":["По́стничеськи преподвиза́вся на горі́, / у́мная враго́в ополче́нія всеору́жієм Креста́ погуби́л єси́, всеблаже́нне. / Па́ки же ко страда́льчеству / му́жеськи обле́клся єси́, / уби́в Копрони́ма мече́м ві́ри; / і обої́х ра́ди вінча́лся єси́ от Бо́га, // преподобному́чениче Андре́є, приснопа́м'ятне."],"h":"Андрію Критському, глас 4"},{"ps":["Блаже́н єси́, о́тче наш Афана́сіє, / я́ко ві́рно пожи́л єси́, стоя́ бо́дренно за святу́ю Правосла́вную ві́ру, / со умиле́нієм при́сно поя́ несіда́льноє Пречи́стій, / запові́дуя нікому́же наруша́ти Правосла́вния ві́ри святи́я, / пострада́в за свиді́тельство і́стини да́же до сме́рти. / Ми же чту́ще святи́ню твою́, / со дерзнове́нієм взива́єм ті: / о́тче наш, преподобному́чениче Афана́сіє, // похвало́ і украше́ніє на́ше."],"h":"Афанасію Брестському, глас 2"},{"ps":["По́стничеськи предподвиза́вся на горі́, / у́мная враго́в ополче́нія / всеору́жієм Креста́ погуби́л єси́, всеблаже́нне. / Па́ки же ко страда́льчеству му́жеськи обле́клся єси́, / уби́в Копрони́ма мече́м ві́ри, / і обої́х ра́ди вінча́лся єси́ от Бо́га, // преподобному́чениче Дометі́є приснопа́м'ятне."],"h":"Доместію Персянину, глас 4"},{"ps":["Пра́востію у́мною ду́шу твою́ прив'яза́вши в любо́в Христо́ву, / тлі́нних, і кра́сних, і вре́менних заби́тієм претекла́ єси́, / я́ко Сло́ва учени́ця: / поще́нієм стра́сті пе́рвіє умертви́вши, / страда́льчеськи второ́є врага́ посрами́ла єси́. / Тім Христо́с сугу́бих вінця́ сподо́би тя, / сла́вная Євдокі́є, преподо́бная страстоте́рпице, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."],"h":"Євдокії Іліопольській, глас 8"},{"ps":["По́стником і му́чеником яви́лся єси́ похвала́, преподо́бне Євстра́тіє, / пре́жде бо воздержа́нієм плоть умертви́в, / послі́довал єси́ Христу́, нося́ крест свой. / Посліди́ же і сам на крест вознесе́н бив / і копіє́м в ре́бра прободе́н, / в ру́ці Бо́жий ду́шу преда́л єси́. / Колесни́цею о́гненною возноси́м на Небеса́, / сугу́бо вінча́лся єси́ от Христа́ Бо́га // і Спа́са душ на́ших."],"h":"Євстратію Печерському, у Ближніх печерах, глас 7"},{"ps":["Равночи́сленії Тро́йці Несозда́нния су́ще, / с ли́ки А́нгелов і чи́ни му́чеников / предстоїте́ ви, ра́дующеся, Престо́лу Божества́, му́дрії. / Сего́ ра́ди прича́стієм сія́ніє отону́ду приє́млюще, / істо́чник ісціле́ній ві́рним подає́те / і Боже́ственноє просвіще́ніє, / му́чениче Христо́в Євфи́міє со Ігна́тієм му́дрим і с Боже́ственним Ака́києм, // о нас при́сно молі́теся."],"h":"Євфимію, Ігнатію й Акакію Афонським, глас 7"},{"ps":["Сою́зом любве́ связа́вшеся, преподо́бнії, / всяк сою́з ко́зней вра́жиїх попра́сте, / страда́ніє же і смерть непови́нне / от сребролюби́ваго кня́зя претерпі́сте до́блі, / тім мо́лим вас, вку́пі пожи́вших / і вінці́ муче́нія приє́мших, / молі́теся Го́сподеві о нас, / я́ко да во мно́зій любві́, ві́рі і наде́жді до́брі пожи́вше, / всегда́ ублажа́єм вас, // Фео́доре і Васи́ліє добропобі́днії."],"h":"Феодору й Василію Печерським, у Ближніх печерах, глас 1"},{"ps":["Тревелича́йшия світи́льники, / всіх преподобному́ченик Богоізбра́нний полк, / два́десять і шесть Боже́ственния оби́телі Зогра́фськия оте́ць, почти́м, / пре́лесть лати́нськую обличи́вшия / і наси́льственно во огні́ сконча́вшіяся; / Фому́ пастиренача́льника, свяще́ннаго Варсоно́фія, / достосла́внаго Парфе́нія і про́чія, подвиза́вшіяся, / соше́дшеся, пі́сньми почті́м, / сії́ бо Тро́йцю Святу́ю // при́сно о нас умо́ляють."],"h":"26-ти преподобномученикам Зографським, глас 1"},{"ps":["Таврио́н сла́вний і Авкт ди́вний, / о́гневі проти́вистася і всім і́нім ка́знем, / моли́твами возмога́юща; / та у́бо моле́нієм сердца́ похваля́юще, / ві́рою пресвяту́ю і честну́ю па́м'ять є́ю соверши́м, // ду́шам просвіще́ніє почерпа́юща."],"h":"Авкту й Таврієві, глас 4"},{"ps":["Страстоте́рпці Госпо́дні, / блаже́нна земля́, напи́вшаяся кровми́ ва́шими, / і свя́та селе́нія, / приі́мшая тілеса́ ва́ша: / в три́знищі бо врага́ побіди́сте / і Христа́ со дерзнове́нієм пропові́дасте: / Того́ я́ко бла́га молі́те // спасти́ся, мо́лимся, душа́м на́шим."],"h":"Акіндину, Пігасію, Аффонію, Елпідифору, Анемподисту й тим, що з ними, глас 2"},{"ps":["Му́жествовавше во Христі́ проти́ву безбо́жнаго царя́, / му́ченици святі́ї, / і того́ неві́ріє іуде́йськоє во Христа́ обличи́вше, / прия́ша мук томле́ніє і глава́м усіче́ніє; / тім восхвали́ша тя А́нгели, / і ві́рних ро́ди тя прославля́ють, Аре́фо, / і пострада́вших с тобо́ю, // я́ко моля́щихся при́сно о душа́х на́ших."],"h":"Арефі й тим, що з ним, 4299-ти, глас 1"},{"ps":["Я́коже А́вель, от суда́ бра́тняго смерть прия́л єси́ / і кров твою́ пролія́л єси́ за Іскупи́вшаго ни честно́ю Своє́ю Кро́вію. / От земна́го же к Небе́сному преста́вився Ца́рствію, / кня́же і му́чениче Єнраво́те-Боя́не, // моли́ Царя́ царе́й о нас, при́сних твої́х."],"h":"Бояну, князю Болгарському, глас 4"},{"ps":["Боже́ственним жела́нієм от ю́наго во́зраста / весь сам себе́ Го́сподеві возложи́в, / в моли́твах і пості́х о́браз бив доброді́телі, / бога́тство же, і сла́ву, і доброро́дство тіле́сноє, я́ко не су́щеє, презрі́в, / і Христа́ єди́наго от душі́ возлюби́л єси́, / і Того́, і́стиннаго су́ща Бо́га, в Тро́йці покланя́єма, / пред нечести́вими ту́рки пропові́дал єси́, / і, сраци́нськую ві́ру, і зако́ни Моаме́фови под нога́ми попра́в / і мучи́теля ужаси́в, / муче́нія вінце́м украси́вся, сла́вне, / к Небе́сним восте́кл єси́ ликостоя́нієм, / прему́дре Гео́ргіє. / Моли́ Христа́ Бо́га / сохрани́ти оте́чество твоє́ і спасти́ лю́ди і град, // і́же твоя́ по́двиги при́сно почита́ющия."],"h":"Георгію Новому, Софійському, глас 4"},{"ps":["Мучи́тельнії сосу́ди устро́їша ті путь к Небесе́м, / Христо́во во́їне Діоми́де, / побіди́в дия́вольськия ко́зні, / і на Небесі́х у Христа́ просла́вися, // моли́ся за творя́щих ві́рою па́м'ять твою́."],"h":"Діомиду, лікареві, глас 3"},{"ps":["Му́ченик всечестни́х сві́тлость, / п'яточи́сленних страстоте́рпцев воспоє́м, / сла́ву земни́х презрі́вших, / со́лнця сві́тлаго Євстра́тія, / прему́драго виті́ю со страда́льці, / на огнь і му́ки дерзну́вших за всіх Царя́ Христа́ / і от престо́ла Того́ сла́ви по́честьми вінце́в обдаре́нних. / Тіх моли́твами, Христе́ Бо́же, // спаси́ ду́ші на́ша."],"h":"Євстратію, Авксентію, Євгенію, Мардарію й Оресту, глас 4"},{"ps":["Крест, я́вльшійся тебі́ с Небесе́, сві́тел пропові́дал єси́, / просвіти́в язи́ки я́сно, Влади́мире сла́вне, / обагре́ньми крове́й твої́х украси́вся, / сподо́бился єси́ по́честей нетлі́нних, / предстоя́й Тро́йце, / тім со дерзнове́нієм // моли́ спасти́ся нам."],"h":"Іоанну-Володимиру, князю Сербському, глас 4"},{"ps":["Страстоте́рпче святи́й Іоа́нне, / блаже́нна земля́, напи́вшаяся кро́ве твоєя́, / Христа́ бо со дерзнове́нієм пропові́дав, / мно́гія му́ки от неві́рних ага́рян прия́л єси́, / страда́ньми свої́ми проти́вних де́рзости низложи́в, / Тро́йці побо́рник яви́лся єси́, // Ю́же і моли́ дарова́ти нам ве́лію ми́лость."],"h":"Іоанну Казанському, мученику, глас 2"},{"ps":["І́же ко Христу́ ві́рою / болі́знь тіле́сную ісціли́, с не́юже і душе́вную, / наставля́єм от честна́го твоєго́ учи́теля Фео́дора, / сла́вний царю́ Моа́віє Іоа́нне, / і, страда́ніє по Христе́ ку́пно с ві́рними твої́ми треми́ о́троки сконча́в, / яви́ся в царі́х му́ченик, в му́чениціх же цар, / по Христе́ тече́ніє сконча́в, от свої́х раб во́лею пострада́, / і, сугу́бу честь от Бо́га приї́м, / Єго́же моли́ ку́пно с треми́ ві́рними твої́ми о́троки // спасти́ся душа́м на́шим."],"h":"Іоанну, колишньому Моавію, цареві Перському, і тим, що з ним, трьом отрокам, глас 6"},{"ps":["Моли́твами Твої́х му́чеников, Го́споди, / благоче́стіє в страні́ Каза́нстей насади́ся, / і, я́ко пла́менем о́гненним. / Правосла́вной ве́рой Восто́к озари́ся, / і ни́ні їх предста́тельством, Человіколю́бче, / не пом'яни́ беззако́ній на́ших, / но утверди́ нас во ві́рі і́стинній // і мир пода́ждь, мо́лимся Ті."],"h":"Іоанну, Стефану, Петру, Борису, Якову, Феодору, Сильвану, Феодору, Василю, Феодору, Димитрію, Михаїлу, Іоанну й Василю Казанським, глас 1"},{"ps":["Я́ко лоза́ благопло́дная, Іули́тто честна́я, / грозд зрел принесла́ єси́ Царе́ві, всіх Бо́гу, / си́на твоєго́ Ки́рика сла́внаго, / му́ченієм того́ бога́тно украси́вши / і твоє́ю кро́вію наверши́вши, / тім і дарова́ тебі́ Ви́шній возме́здіє во Ви́шніх, // іді́же лику́юще, пом'яні́те нас, му́ченици терпіливоду́шнії."],"h":"Кирику й Іуліті, глас 8"},{"ps":["Му́ченик дво́їця єдинонра́вная, / Маркія́н с Марти́рієм сла́вним, А́рієво нече́стіє разруши́ша / і Соприсносу́щна Си́на Отцю́ і Ду́хові ві́ровати научи́ша, / Па́влу повину́ющеся і́стинних повелі́ній учи́телю, / ті́мже мече́м убіє́ни, умро́ша; / і при́сно со Христо́м живу́ще, / о нас Того́ мо́лять // спасти́ ду́ші на́ша."],"h":"Маркіяну й Мартирію, глас 1"},{"ps":["Возсія́в, я́ко звізда́ многосві́тлая, / в собо́рній це́ркві пред пречи́стим і чудотво́рним о́бразом Пречи́стій Богоро́диці, / за Ню́же і за град Смоле́нск пострада́, / многоко́зненнаго і богоме́рзькаго царя́ Бати́я устраши́, / і си́льнаго ісполи́на побіди́, і лю́ди удиви́, / ду́шу свою́, многострада́льне Мерку́ріє, за благоче́стіє положи́, / я́ко Заха́ріїна і А́велева я́сно вопіє́ть твоя́ кров ко Го́споду. // І ни́ні моли́ся за ду́ші на́ша."],"h":"Меркурію Смоленському, воїну, глас 2"},{"ps":["Воздержа́нієм страсте́й огнепа́льния / умертви́вше зра́ки і движе́нія, Христо́ви му́ченици, / прия́ша благода́ть неду́ги отгоня́ти немощни́х, / і жи́вше і по кончи́ні чудоді́йствовати; / воі́стину чу́до пресла́вно, / я́ко ко́сті на́ги істоча́ють ісціле́нія, // сла́ва Єди́ному і Созда́телю Бо́гу."],"h":"Мині, Єрмогену й Євграфу, глас 8"},{"ps":["Доброму́ченице Миропі́є і Христа́ неві́сто нетлі́нная, / ни́ні Єму́же предстої́ши, прекра́сная, / ра́ни нося́щи пло́ті, / я́ко ка́мни сві́тли і светообра́зни, / і в крова́вую порфи́ру, я́ко цари́ця, облече́нная, пресла́вная, / умоли́ Єго́ за ни, / я́же с любо́вію восхваля́ющия // хвали́ побі́дними і пі́сньми твою́ Боже́ственную страсть."],"h":"Миропії, глас 1"},{"ps":["От до́бляго наста́вника Фео́дора / чистоту́ тве́рдо ізви́че, / і от нече́стія цари́ці Сеї́ди / цілому́дрієм по о́бразу Іо́сифа сохрани́ся, / та́коже і нечести́ваго царя́ Адрамеле́ха / прему́дрими твої́ми глаго́ли прі́нія і ласка́нія низложи́в, / і по Христе́ муче́нія вінце́м ув'язе́ся, / Богому́дрий Михаї́ле, // Єго́же моли́ спасти́ ду́ші на́ша."],"h":"Михаїлу Сновидцю, глас 5"},{"ps":["Жизнь ва́шу му́ченичеськи соверши́вше, / іспові́данія вінці́ укра́сившеся, к Небе́сним востеко́сте, / Михаї́ле прему́дре с до́блим Фео́дором, / молі́те Христа́ Бо́га / сохрани́ти оте́чество ва́ше / град же і лю́ди, // по вели́цій Єго́ ми́лості."],"h":"Михаїлу, князю Чернігівському, і боярину його Феодору, чудотворцям, мученикам і сповідникам, глас 4"},{"ps":["Тро́їчнаго Божества́ осія́нієм просвіти́вся, / страстоте́рпче вели́кий кня́же Михаї́ле, / с прему́дрим боля́рином ті Фео́дором, / самозва́нна к по́двигом устріми́стася, / сквозі́ огнь не ідо́ста, / кусту́ же і і́долом не поклони́стася, но оплева́ста / і нечести́ваго царя́ обличи́ста, / Христа́ же Єди́наго от Тро́йці Бо́га Су́ща іспові́даста. / І того́ ра́ди крове́й свої́х струя́ми обагри́стася, сла́вная. / Ті́мже і вінця́ от Него́ побі́дная прия́ста, / і нас сви́ше назира́єта, / мо́лим вас, святи́я, молі́те Того́, / я́ко да ва́шими моли́твами ізба́вить нас от вся́ких обстоя́щих ни зол / і пода́сть нам вся блага́я, // і́же Єди́н Сий прославля́ємий во святи́х Свої́х."],"h":"Михаїлу, князю Чернігівському, і боярину його Феодору, чудотворцям, мученикам і сповідникам, другий тропар, глас 8"},{"ps":["Одолі́нієм чуде́сним / побіди́ла єси́ вра́жия си́ли до конця́, / Неде́ло пресла́вная, / ідоложре́нія бо тьму / дале́че Креста́ честна́го сві́тлостію прогна́ла єси́. / Му́ченице всехва́льная, / Христу́ Бо́гу моли́ся // дарова́ти нам ве́лію ми́лость."],"h":"Кіріакії Нікомидійській, глас 3"},{"ps":["Удо́м усікнове́ніє терпі́л єси́ / і о́гненную лю́тую му́ку, му́чениче, / подви́гся, всесла́вне, / вінце́м я́ві ув'язе́ся нетлі́нним, преблаже́нне, / Престо́лу же предстої́ши Святи́я Тро́йці, / Ю́же помоли́, да спасе́ть ни, / му́чениче Оре́сте, // ві́рою пою́щим тя."],"h":"Оресту, лікареві, глас 4"},{"ps":["Му́чеников дво́їця єдинонра́вная, / Стефа́не і Пе́тре сла́внії, / неві́ріє соплеме́нников обличи́вше, / Христу́ послі́довали єсте́, / во Святу́ю Тро́йцю ві́ровати всіх науча́юще, / Єя́же ра́ди вели́кия страда́нія приє́мше, / молі́теся о нас ко Го́споду, / да, ізба́вившеся тьми гріхо́вния, / Сві́та яві́мся о́бщници невече́рняго."],"h":"Петру й Стефану Казанським, глас 4"},{"ps":["Земна́го са́на по́яс оста́вив і по́чести, страда́льче, / пред мучи́телем, льсти́вим царе́м, / Христа́ Бо́га су́ща іспові́дал єси́, / і Того́ ра́ди мно́га страда́нія под'я́л єси́, сла́вне. / Тім прекра́сним побі́ди вінце́м ув'я́злся єси́ / от Царя́ всіх ца́рствующаго, / с Небе́сними во́ї сві́тло преукра́шен. / Предстоя́ Тому́, Са́вво, // моли́, да спасе́ть ду́ші на́ша."],"h":"Саві Стратилату й з ним 70-ти воїнам, глас 5"},{"ps":["Неві́сто Христо́ва возлю́бленная, Серафи́мо, / наслі́днице Ца́рствія Небе́снаго, / до́брі за Го́спода пострада́вшая / і кро́вію твоє́ю обагре́нная / і, а́ки ца́рською багряни́цею, украше́нная, // помина́й нас, соверша́ющих святу́ю па́м'ять твою́."],"h":"Серафимі діві Римській, глас 8"},{"ps":["Удобре́ніє Христо́вих страстоте́рпець, / і о́чі Христо́ви Це́ркве, / о́чі просвіті́те душ на́ших, / Се́ргіє многострада́льне і Ва́кше пресла́вне: / молі́теся ко Го́споду, / я́ко да убіжі́м тьми гріхо́вния, / і сві́та яві́мся о́бщници невече́рняго, // моли́твами ва́шими, святі́ї."],"h":"Сергію й Вакху, глас 5"},{"ps":["В Тро́йці хвали́мий Бог тро́йцю му́ченик просла́ви, / Трофи́ма і Савва́тія і Доримедо́нта: / в Того́ бо ві́ровавше, врага́ низложи́ша. / Тіх моли́твами, Христе́ Бо́же наш, поми́луй нас."],"h":"Трофиму, Савватію й Доримедонту, глас 8"},{"ps":["Я́ко во́їни, му́ченици непобіди́мії, / тече́нієм невозбра́нним в суди́лище неві́рних внидо́сте / і ві́ри ра́ди мно́гія му́ки претерпі́сте, / Христа́ іспові́дающе Єди́наго со дерзнове́нієм. / Того́ молі́те, Трофи́ме і Фео́филе с про́чими, / я́ко да тяготу́ страсте́й отло́жше, // ва́ше ни́ні страда́ніє поє́м, страстоте́рпці непреобори́мії."],"h":"Трофиму, Феофілу й з ними 13-ти мученикам, глас 4"},{"ps":["Доброді́тель благоприя́тно, му́ченице, пости́гла єси́, / Христо́во прия́телище би́вши чи́стоє, / і Свята́го Ду́ха дом возлю́блен; / отню́дуже посрами́ла єси́ врага́, борю́щаго род челові́чеський, / до́брі страда́вшая, / і посі́кла єси́ Копрони́ма, Феодо́сіє, мече́м ві́ри, / і к черто́гу Небе́сному преста́вилася єси́, ра́дующися. / Тебі́ ві́рою чту́щим // при́сно проси́ ве́лія ми́лости."],"h":"Феодосії Константинопольській, глас 4"},{"ps":["Преудо́бренную і богому́друю дво́їцю пресві́тлую / восхва́лим, ві́рнії, по достоя́нію, / Фло́ра преблаже́ннаго і Ла́вра всечестна́го, / і́же усе́рдно Тро́йцю несозда́нную я́сно пропові́дасте всім, / ті́мже пострада́вше до кро́ве, / і вінці́ пресві́тлими ув'язо́стеся, // молі́теся Христу́ Бо́гу, да спасе́ть ду́ші на́ша."],"h":"Флору й Лавру, глас 4"},{"ps":["Зва́нієм єва́нгельськи Христу́ уневі́стившися, / Христи́но сла́вная, / сла́ву ми́ра сего́ і по́хоть бре́нную вміни́ла єси́ ні во что же, / о само́м тілесі́ небрегу́щи, / му́ки претерпі́ла єси́ до́блественно, / тім твоє́ страда́ніє хвала́ми почита́єм, // му́ченице, Христу́ тезоімени́тая."],"h":"Христині Тирській, глас 4"},{"ps":["Оде́ждами от крове́й украша́яся, / Го́сподеві предстої́ши, Царю́ сил, Христофо́ре приснопа́м'ятне, / отону́дуже со Безпло́тними і му́ченики поє́ши / трисвяти́м і стра́шним сладкопі́нієм. / Ті́мже моли́твами твої́ми спаса́й ста́до твоє́."],"h":"Христофору Лікійському, глас 4"},{"ps":["Многочу́дний Крить почти́м, / процві́тшій честни́я цвіти́, / Христо́ви би́сери, / му́чеников сора́слених, / де́сять бо суть число́м, блаже́ннії, / і́же весь і́дольський наро́д посрами́ша, // ті́мже і вінці́ прия́ша, добледу́шнії."],"h":"10-ти мученикам Критським, глас 3"},{"ps":["Єдиноу́мне душе́ю свя́зани би́вше, / чети́редесять с п'ятьми́ страда́льці святі́ї, / на врага́ ополчи́стеся, / побіди́теліє же я́вльшеся, / прия́сте вінці́ от Христа́ Бо́га / і ві́чноє муче́ній ва́ших воздая́ніє, / ти́я і нам улучи́ти молі́те, // благоче́стно пі́сньми вас велича́ющим."],"h":"45-ти мученикам Нікопольським (Вірменським), глас 1"}],"notes":[]},{"u":"Тропарі безсрібникам","e":"Troparia of the unmercenary healers","secs":[{"ps":["Тро́їчная благода́ть все́льшися в честна́я сердця́ ва́ша, / преблаже́ннії Ки́ре і Іоа́нне, / на ду́хи нечи́стия стра́шни прогони́теліє яви́стеся. / І не то́чію явле́нним, но та́йним неду́гом вра́чеве би́сте, / тім же, дерзнове́ніє іму́ще к Человіколю́бцю Бо́гу, // непреста́нною моли́твою душе́вния на́ша стра́сті ісцілі́те."],"h":"Мученикам і безсрібникам Киру й Іоанну Олександрійським, інший тропар, глас 5"}],"notes":[]},{"u":"Тропарі праведним і блаженним","e":"Troparia of the righteous and the blessed","secs":[{"ps":["Сте́блю Леві́їна ко́рене, / приіми́й чин дре́вняго Мафусаї́ла, / он бо о́тча ра́ди к Бо́гу вознесе́нія, / ти же бра́тня ра́ди с Бо́гом бесі́дованія, / первосвяще́нний во Ізра́їлі моле́бниче о всіх, / умоли́ Бо́га ку́пно с бра́том свої́м богови́дцем, // да ізба́вимся от вся́кия ско́рби."],"h":"Аарону, первосвященнику, праведному, глас 3"},{"ps":["Жизнь ро́ждшую во чре́ві носи́ла єси́, Чи́стую Богома́тер, / Богому́драя А́нно. / Ті́мже к прия́тію Небе́сному, іді́же веселя́щихся жили́ще, / в сла́ві ра́дующися, ни́ні преста́вилася єси́, / чту́щим тя любо́вію / прегріше́ній прося́щи очище́ніє, // присноблаже́нная."],"h":"Анні, праведній, глас 4"},{"ps":["Бога́тство ви́дів чи́стия душі́ твоєя́, Васи́ліє, / укра́сти тща́шеся пра́ведних враг, / подусти́ господи́на твоєго́, / і́же покраденнаго ра́ди бога́тства своєго́ преда́в тя судії́, / і от того́ неповинне мно́гія претерпі́л єси́ муки́, / непобіди́м преби́в до сме́рти. / Тім, я́ко приє́мий віне́ць страда́нія от всіх Влади́ки, / моли́ всім от напа́стей свобо́дним би́ти, / чту́щим любо́вію святу́ю па́м'ять твою́."],"h":"Василю Мангазейському, мученику, праведному, глас 8"},{"ps":["От гра́да Яросла́вля Бо́жиїм смотре́нієм / в страну́ Сиби́рськую прише́дшаго / і за целому́дріє от господи́на своєго́ / в Мангазе́ї пострада́вшаго, / блаже́ннаго Васи́лія почти́м, / єго́же Христо́с Бог му́ченичеським вінце́м вінча́ на Небесі́, / нетлі́нієм і чудеси́ просла́ви на землі́. / Ти же, честни́й страда́льче, / предста́тельством свої́м страну́ на́шу в ми́рі сохрани́ // і моли́ся о спасе́нії душ на́ших."],"h":"Василю Мангазейському, мученику, праведному, інший тропар, глас 8"},{"ps":["Всера́достноє дарова́ніє от Бо́га / святи́м жена́м – святи́я ді́ти; / всера́достноє дая́ніє і тебі́, свята́я Євву́ло, – / святи́й великому́ченик Пантелеї́мон, / ми́лости тезоимени́тий, / неду́гующих ціли́тель і наш засту́пник. / Сла́ва у́бо о вас Всеми́лостивому Влади́ці, / сла́ва Подаю́щему ва́ми цільби́, // сла́ва предста́телі на́ші вас Показа́вшему."],"h":"Євбулу, праведному, глас 1"},{"ps":["От землі́ воззва́вий тя к Небе́сним селе́нієм / соблюда́єть і по сме́рті невреди́мо ті́ло твоє́, свя́те Євдоки́ме: / ти бо в цілому́дрії і чи́стом жи́тельстві, блаже́нне, / жи́тельствовал єси́, не оскверни́в пло́ті. // Ті́мже со дерзнове́нієм моли́ Христа́ Бо́га спасти́ся нам."],"h":"Євдокиму Каппадокіянину, праведному, глас 4"},{"ps":["І́же Боже́ственним раче́нієм подви́гся / на отмще́ніє проли́тия кро́ві пра́ведних, / я́ко Дави́д от Самуї́ла, / ти же от Зино́на преди́внаго, / проро́чеськи я́же сби́тися тебі́ предре́кша, / є́же обіща́нієм к нему́, / і того́ благослове́нієм побі́ди на враги́ і одолі́нія показа́вшу, / отню́ду же со отложе́нієм ца́рства / по́стних селе́ній гори́ жизнь соверши́, Єлезво́є царю́, / моли́ Небе́снаго Царя́ Христа́ // спасти́ ду́ші на́ша."],"h":"Елезвою, цареві Ефіопському, блаженному, глас 4"},{"ps":["Вели́ка імі́єть тя предста́теля, Богому́дре, / правосла́вних собра́ніє, / я́коже у́бо преподо́бних єси́ собесі́дник / і Боже́ственния прему́дрости соприча́стник, / та́ко, пречу́дне Ієрони́ме, / Христу́ Бо́гу моли́ся // дарова́ти нам ве́лію ми́лость."],"h":"Єроніму Стридонському, блаженному, глас 3"},{"ps":["Ди́вен, творя́й пресла́вная чудеса́ / і прославля́яй по кончи́ні сла́в'ящия Тя, / нетлі́нная тілеса́ їх явля́я / і чудоді́йствії лю́ди обогаща́я / во сла́ву свята́го і́мені Своєго́, / дарова́вий нам ті́ло уго́дника Своєго́ Іоа́нна, // моля́щагося о душа́х на́ших."],"h":"Іоанну, деспоту Сербському, блаженному, глас 4"},{"ps":["Нагото́ю тіле́сною і терпі́нієм / обнажи́л єси́ вра́жия кова́рствія, / облича́я неподо́бноє єго́ дія́ніє, / зі́льні стражда́ со́лнечний вар, / і ну́ждния вели́кия сту́дені мра́за, / і огня́ не чул єси́, / Бо́жиєю по́мощію покрива́єм, / Іоа́нне прему́дре, / моли́ с ві́рою творя́щих па́м'ять твою́ че́стно / і усе́рдно притека́ющих к ра́ці моще́й твої́х, // ізба́витися от бід і паде́нія ізбіжа́ти."],"h":"Іоанну, Христа ради юродивому, Устюзькому, блаженному, глас 5"},{"ps":["Я́ко вели́ко сокро́вище і бога́тство некрадо́мо / к нам при́йде із Кі́пра, Ла́заре, / Про́мислом всіх Бо́га, повелі́нієм царя́ благочести́ва, / подая́ чту́щим тя исцеле́нія да́ром, / ізбавля́я от бід і от вся́каго вре́да, / ві́рою взива́ющих ті: // спаси́ всіх моли́твами свої́ми, Ла́заре о́тче наш."],"h":"Лазарю Чотириденному, єпископу Кітійському, праведному, глас 4"},{"ps":["Слове́нська язи́ка, Пско́вськия землі́ / пло́тськи в юро́дстві бив, / юро́дства притворе́нієм Го́рняго Ієрусали́ма граждани́н яви́ся, / А́нгелом, сла́вне, свесели́шися, / мироточи́ваго святи́теля Никола́я зва́ніє восприї́м, / с ни́мже всегда́ Христа́ Бо́га моли́ // дарова́ти нам ве́лію ми́лость."],"h":"Миколаю, Христа ради юродивому, Псковському, глас 4"},{"ps":["І́же на землі́ Христа́ ра́ди во́лею в бу́йство преложи́ся, / і ми́ра сего́ красо́ти отню́д возненави́ді, / і плотська́я ігра́нія ув'яди́в посто́м і жа́ждою / і на землі́ лега́нієм, / от зими́ студе́нію і мра́зом, / і от зно́я со́лнечнаго і дождя́ / і про́чія тяготи́ нікогда́ же уклони́ся под кров, / і на ті́лі своє́м не імі́я одія́нія, / Бо́жиєю по́мощію покрива́єм, / і ду́шу очи́стил єси́ доброді́тельми свої́ми, я́ко зла́то в горни́лі, / Проко́піє прему́дре, / с ві́рою творя́щим па́м'ять твою́ че́стно / і усе́рдно притека́ющим к моще́м твої́м, / прославля́юще твоє́ свято́є успе́ніє, / Христу́ Бо́гу моли́ся, благою́роде, / да ізба́вить ни Госпо́дь от ва́рварськаго наше́ствія і междоусо́бния бра́ні / і мир ми́рові да́руєть // і душа́м на́шим ве́лію ми́лость."],"h":"Прокопію, Христа ради юродивому, В’ятському, блаженному, глас 4"},{"ps":["Я́ко воі́стину гла́са апо́стольськаго / послу́шатель бил єси́, блаже́нне Си́моне, / Христа́ бо ра́ди ізво́лив імі́ти бу́йство, / в не́мже соблю́л єси́ твоя́ к Бо́гу доброді́телі, посреді́ молв некра́доми, / терпі́нієм у́бо пачеєсте́ственним Христу́ подража́в, / посрами́л єси́ льсти́ваго всю горди́ню, / тім і в лю́тих ра́нах, я́коже дре́вній Ла́зар, / в ні́дра Авраа́мля пресели́лся єси́, / іді́же і ни́ні утеша́яся, посіща́й град твой, // почита́ющий любо́вію святу́ю па́м'ять твою́."],"h":"Симону, Христа ради юродивому, Юр’євецькому чудотворцю, блаженному, глас 8"},{"ps":["Ти на землі́ вседу́шно Христа́ возлюби́в / і Того́ за́повіді соблюда́я, / я́ко ріка́, благоутро́бієм ізсо́хших нището́ю бога́тно напої́л єси́ / і лю́ди своя́ снабді́л єси́, / і ра́ка моще́й твої́х благоуха́нія цільби́ всім подає́ть, / сего́ ра́ди, свя́те, мо́лим тя, // ізпроси́ душа́м на́шим ве́лію ми́лость."],"h":"Стефану Милютину, королю Сербському, праведному, глас 3"},{"ps":["Ю́ношеськи процві́л єси́ / во оте́чествії твоє́м, добро́тою украше́н, / і непра́ведную і безвре́менную смерть под'я́л єси́, / У́роше всече́стне; / ца́рськаго ко́рене плод сла́док, / а́ще і не во вре́м'я созре́в, / в Госпо́дню жи́тницю всели́лся єси́ / і жа́лость ве́лію сро́дству твоєму́ оста́вил єси́. // Моли́ся о нас, творя́щих святу́ю па́м'ять твою́."],"h":"Стефану Урошу V, королю Сербському, глас 3"},{"ps":["Днесь ві́ра Христо́ва утвержда́ється ка́менем ві́ри, / і ликовству́єть во весе́лії Іоппі́я, / псало́мськи славосло́в'ять Жизнода́вця Си́на Бо́жия ві́рнії, / ви́дяще соверша́ємо ве́ліє чу́до: / первоверхо́вний апо́стол глаго́леть, / і уме́ршая востає́ть от гро́ба, / ю́же Низложи́тель сме́рті да́руєть Це́ркві, / да украша́ються во о́браз єя́ доброді́тельми лю́ди. / Прийді́те у́бо, христия́не, / принесе́м ко святі́й моле́нія на́ша: / блаже́нная Тави́фо і милосе́рдная, / вознеси́ на́ша воздиха́нія Пресвяті́й Тро́йце, / і моли́ся со дерзнове́нієм, / да си́нове сві́та Преві́чнаго бу́дем, / да сподо́бимся Бо́жия ми́лості, / да пребива́єм в любві́ Боже́ственній, // і да ца́рствуєть мир во вселе́нній."],"h":"Тавіфі, праведній, глас 4"},{"ps":["Апо́столом сотаї́ннице, ми́лостивая Тави́фо, / оби́телі же́нськия нача́ло положи́ла єси́ / і бі́дним одія́ніє била́ єси́, / послу́шнице смире́нная, / сло́ву апо́стола Петра́ повину́вшися, / із ме́ртвих си́лою Христо́вою возста́ла єси́ / і ни́ні на Небесі́х сві́тло пра́зднуєши. / Ті́мже моли́ Христа́ Бо́га // всім, помина́ющим тя, дарова́ти живо́т ві́чний."],"h":"Тавіфі, праведній, інший тропар, глас 4"}],"notes":[]},{"u":"Тропарі благовірним князям і царям","e":"Troparia of the holy princes and kings","secs":[{"ps":["Наста́ днесь всечестни́й но́вий пра́здник, / обрі́теніє честни́х моще́й / блаже́ннаго кня́зя Гавриї́ла, / веселя́щи ізря́дно всіх благочести́вих мно́жества, / ті́мже всі ві́рнії, / соше́дшеся во святи́й храм Живонача́льния Тро́йці, возопіє́м: / блаже́нне кня́же Гавриї́ле, / імі́я дерзнове́ніє ко Христу́ Бо́гу, // моли́ спасти́ся пра́зднующим любо́вію па́м'ять твою́."],"h":"Всеволоду, у святому Хрещенні Гавриїлу, Псковському, благовірному князю, інший тропар, глас 4"},{"ps":["На висоті́ вели́каго княже́нія сідя́, / яви́лся єси́, благоче́стієм і ві́рою сія́я оте́честву своєму́, я́ко со́лнце; / по Святі́й Тро́йці ре́вностію разже́гся / і за ві́ру крі́пко пострада́в, кров твою́ пролія́л єси́. / Тім і отсі́ченая твоя́ за Христа́ глава́ свиді́тельствуєть я́ві о тебі́, / прилі́пшая по сме́рті к тілесі́ твоєму́, / с не́юже і до днесь нетлі́нни пребива́ють мо́щі твоя́, / от ни́хже істоча́єши ісціле́нія душа́м і тілесе́м на́шим. / Но я́ко дерзнове́ніє імі́я ко Христу́, страстоте́рпче Гео́ргіє, / непреста́нно моли́ держа́ву твою́ і сро́дник твої́х // безвре́дну сохрани́ти моли́твами твої́ми."],"h":"Георгію (Юрію) Всеволодовичу Володимирському, благовірному великому князю, глас 8"},{"ps":["Днесь сві́тло красу́ється сла́внійший град Влади́мир, / імі́я в себі́ пребога́тоє сокро́вище — / чудоточа́щия честни́я мо́щі благові́рнаго кня́зя Глі́ба, / і́миже украша́яся і хваля́ся, / вселе́нную всю созива́єть к весе́лію / і велегла́сно вопіє́ть: / о Влади́ко Христе́, / дарова́вий такову́ю благода́ть уго́днику Твоєму́, // єго́ моли́твами поми́луй нас."],"h":"Глібу Володимирському, благовірному князю, глас 4"},{"ps":["В по́стничестві от ю́ности до́брі подвиза́вся, Богому́дре, / ум на враги́ му́жеськи вооружи́в, / ору́жієм кре́стним сих побіди́л єси́, / твердому́дростная повлача́, в ду́шу вложи́ свою́. / Ті́мже похваля́єм тя, кня́же наш Глі́бе, / я́ко по́стником ти єси́ удобре́ніє, / Ки́єву — сла́ва // і всей Ру́сстій землі́ — утвержде́ніє."],"h":"Глібу Всеволодовичу Городенському (що в Києві), благовірному князю, глас 2"},{"ps":["І́же о́тчеє нече́стіє возненави́дів, / преблаже́нне кня́же Дома́нте, / і но́щі стра́стния ізбі́г, є́же к і́долом тща́ніє, / приї́де ми́слію к Со́лнцю сла́ви — Христу́, / озари́вся благода́тію Боже́ственнаго Креще́нія, / і ни́ні во сві́ті Пресвяти́я Тро́йці предстоя́, / моли́ Христа́ Бо́га сохрани́ти і спасти́ правосла́вния лю́ди / і град твой от безбо́жних ага́рян, / і лати́н наше́ствія, і междоусо́бния бра́ні // і спасти́ся душа́м на́шим."],"h":"Довмонту, у святому Хрещенні Тимофію, Псковському, благовірному князю, глас 8"},{"ps":["Константи́н днесь ве́село ликовству́єть, / предстоя́ Престо́лу Святи́я Тро́йці, / ви́дя оте́чествіє своє́, ма́стію духо́вною сія́ющеє; / єму́же послі́доваша Михаї́л і Фео́дор, си́нове єго́, // і мо́ляться всі тріє́ вку́пі о душа́х на́ших."],"h":"Костянтину (Ярославу) і дітям його Михаїлу й Феодору, Муромським чудотворцям, глас 4"},{"ps":["Красоту́ возжелі́в сла́ви Бо́жия, в земні́й Тому́ благоугоди́л єси́ і, поруче́нний ті тала́нт до́брі возді́лав, усугуби́л єси́, о не́мже і подвиза́вся до кро́ве. Отону́дуже і мзду болі́зней твої́х, я́ко му́ченик, прия́л єси́ от Христа́ Бо́га: Єго́же моли́ спасти́ся пою́щим тя, Ла́заре."],"h":"Лазарю, благовірному князю Сербському, глас 3"},{"ps":["Во святи́х ди́вная, / Іве́рії світи́ло, / благові́рная цари́це Тама́ро, / на гора́х висо́ких хра́ми воздви́гшая, / да в них моле́нія возсила́ють ко Го́споду, / мольба́ми твої́ми крі́пость дарова́вшая во́єм христолюби́вих люде́й страни́ І́верськия, / десни́цею же своє́ю по́лчища ага́рянськая низпрове́ргшая, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."],"h":"Тамарі, цариці Грузинській, благовірній, глас 4"},{"ps":["В жи́зні сей утверди́ся ві́рою, / в за́повідіх Госпо́дніх пребива́ше непрекло́нен, / благоугоди́х Тому́, я́ко благочести́в самоде́ржець / Єму́же подо́б'яся о вруче́нних ті христоімени́тих лю́діх, / ду́шу свою́ положи́ти потща́вся, / в зе́млю ідя́ше всезлу́ю і безбо́жную / і та́мо, пред нечести́вим мучи́телем Христа́ дерзнове́нно іспові́дав, / му́ченичеський віне́ць прия́т, / ті́мже, прему́дре Фео́доре Яросла́виче, / Ізба́вителя моли́ ізба́вити от бід оте́чество твоє́ і лю́ди, // да тя всі непреста́нно почита́єм."],"h":"Феодору Ярославичу Володимирському, благовірному князю, глас 8"},{"ps":["От благочести́ваго ко́рене о́трасль благочести́вая прозя́бл єси́ / і, сконча́вся в ю́ності, лі́та до́лга твої́ми доброді́тельми іспо́лнил єси́, / благові́рний кня́же Фео́доре, / сего́ ра́ди Владі́ющему времена́ми мо́лимся, / да моли́твами твої́ми пода́сть нам долготу́ літ // і низпосле́ть страні́ на́шей ве́лію і бога́тую ми́лость."],"h":"Феодору Ярославичу Новгородському, благовірному князю, глас 8"},{"ps":["От ю́ности ва́шея Христо́ві любві́ приліпи́вшеся, святі́ї, / усе́рдно зако́н і оправда́нія Того́ сохрани́сте, / отону́дуже і чуде́сними дарова́ньми обогати́вшеся, / ісціле́нія істоча́єте, / Фео́доре, Дави́де і Константи́не, / о ві́рою вас почита́ющих, / молі́те Христа́ Бо́га, // спасти́ся душа́м на́шим."],"h":"Феодору Смоленському і дітям його Давиду й Костянтину, благовірним князям, глас 4"},{"ps":["Ізмла́да яви́стеся святі́ї, / Богому́дре Фео́доре і блаже́нне Дави́де с Константи́ном сла́вним, / Боже́ственнії сосу́ди, ізбра́ннії Бо́гові. / Ни́ні же істоча́єте нам мно́га ісціле́нія от честни́х моще́й ва́ших, / вся є́ресі потопля́юще, / і спаса́юще при́сно град свой, / і всіх ві́рних сохраня́юще невреди́мо / от ви́димих і неви́димих враг. / Ті́мже ві́рою мо́лим вас, святі́ї: / молі́те Христа́ Бо́га // в ми́рі сохрани́тися нам і спасти́ ду́ші на́ша."],"h":"Феодору Смоленському і дітям його Давиду й Костянтину, благовірним князям, другий тропар, глас 4"},{"ps":["Я́ко зві́зди многосві́тлия от ю́ности возсія́вше, / освіти́ли єсте́ сердца́ ві́рних пренесе́нієм честни́х моще́й ва́ших, / во пло́ті я́ко А́нгели на землі́ показа́стеся, / поще́нієм насажде́ні би́сте, / я́ко древа́ при вода́х воздержа́нія, / напоє́ни струя́ми слез ва́ших, і скве́рну оми́сте. / Сего́ ра́ди яви́стеся прия́телища Бо́жия Ду́ха, / Фео́доре, і Дави́де, і Константи́не, // молі́те Христа́ Бо́га, спасти́ся душа́м на́шим."],"h":"Феодору Смоленському і дітям його Давиду й Костянтину, благовірним князям, третій тропар, глас 8"}],"notes":[]},{"u":"Тропарі соборам святих","e":"Troparia of the synaxes of saints","secs":[{"ps":["Собо́р ваш честни́й почита́юще / і па́м'ять святу́ю пра́зднующе, / святі́ї, от бо́лгар просія́вшії, / прилі́жно мо́лим ви: / Го́спода о всіх молі́те, / па́че же о при́сних, / сохрани́тися землі́ Бо́лгарстей от вся́ких бід / і наро́ду утверди́тися на ві́ки во ві́рі Правосла́вній, / я́ко да, ми́рноє житіє́ благоче́стно пожи́вше, / вку́пі с ва́ми улучи́м ві́чноє Оте́чество // в блаже́ннім Христа́ Бо́га Ца́рствії."],"h":"Усім святим Болгарським, глас 4"},{"ps":["Приспі́ день сві́тлаго торжества́, / лю́дії Воли́нстії ра́дуються, / і с ни́ми вся Россі́йськая Це́рков ликовству́єть / во псалмі́х і пі́ніїх, і пі́сніх духо́вних, / днесь бо, я́коже со́лнце незаходи́моє, / всім возсія́ па́м'ять / святи́х і Богому́жних уго́дников і чудотво́рцев Воли́нських / святи́теля Стефа́на чу́днаго, / ієра́рхом Воли́нським первопресто́льника, / і свята́го благові́рнаго Яропо́лка, / блаже́ннаго страда́льця Богому́жнаго, / і с ни́ми Амфило́хия, святи́теля Воли́нськаго, / і побідоно́снаго Фео́дора, Остро́жськаго кня́зя Богодарова́ннаго, / і преподо́бнаго І́ова Поча́євськаго присноблаже́ннаго, / ї́хже моли́твами, Го́споди, / зе́млю оте́чеськую на́шу в Правосла́вії і ми́ре утверди́, / і спаси́ всіх іму́ще ку́пно о нас Моли́твенницю усе́рдную, / Пресвяту́ю Ма́тер Свою́ Богоро́дицю, / благода́тне сія́ющую в цільбоно́сній стопі́ Своє́й / і чудотво́рній іко́ні на горі́ Поча́євстій / і заступле́ньми про́чих уго́дников Воли́нськия па́стви, / Іулія́нії, блаже́нния ді́ви Ольша́нския, // і свята́го преподобному́ченика Мака́рія, архімандрі́та О́вручськаго."],"h":"Собору всіх Волинських святих"},{"ps":["Столп огнезра́чний і світоно́сноє со́лнце, / возсія́вшеє на горі́ Пече́рстій, / вели́каго Анто́нія со всім собо́ром Богоно́сних оте́ць / приво́дим Тебі́, Христе́, в моли́тву, / ї́хже ра́ди мо́лим, / пода́ждь оби́телі на́шей благода́ть // і душа́м на́шим ве́лію ми́лость."],"h":"Собору преподобних отців Києво-Печерських, у Ближніх печерах, глас 4"},{"ps":["Днесь град Кострома́ вельми́ ва́ми хва́литься: / в преді́ліх бо землі́ Костромськи́я, / я́ко зві́зди світоза́рния, возсія́вше, / чудеси́ свої́ми вся озари́ли єсте́ / і ни́ні мо́літеся ко Го́споду, отці́ преблаже́ннії, Генна́діє, Паї́сіє, Авраа́міє, / Іа́кове, Мака́ріє і Пахо́міє, со іни́ми мно́гими на́шего кра́я Небе́сними покрови́телями / за град Кострому́ і всяк град, і страну́, і лю́ди, / ві́рою і любо́вію вас почита́ющия, // і о спасе́нії душ на́ших."],"h":"Собору Костромських святих, глас 4"},{"ps":["Пусти́нноє житіє́ возлюби́вше, преподо́бнії отці́, / яви́стеся Новгоро́дстей страні́, я́ко іно́є со́лнце, / озаря́юще сію́ мо́лніями чуде́с ва́ших, / і просвіща́єте ві́рою воспіва́ющих вам: // ра́дуйтеся, по́стников похвало́ і пра́ведних удобре́ніє."],"h":"Собору Новгородських святих, глас 4"},{"ps":["Собо́ре святи́х землі́ Смоле́нськия, / вода́ми свяще́ннаго Днепра́ омове́нния, / святи́теліє, преподо́бнії, страстоте́рпці і благові́рнії, / апо́стольськую ві́ру соблю́дшії, / се ни́ні, Святі́й Тро́йці с Богоро́дицею і ли́ки Безпло́тних предстоя́ще, / вода́ми благоче́стія зе́млю Ру́ськую напая́єте, / да́рующе правосла́вним по́мощ Небе́сную / во утвержде́ніє ві́ри // і спасе́ніє душ на́ших."],"h":"Собору Смоленських святих, глас 4"}],"notes":[]},{"u":"Богородичні воскресні (на стиховні)","e":"Sunday theotokia (at the aposticha)","secs":[{"ps":["Се іспо́лнися Іса́їїно прорече́ніє: / Ді́ва бо родила́ єси́ / і по рождестві́, я́ко пре́жде рождества́, пребила́ єси́, / Бог бо бі Рожде́йся, ті́мже і єстества́ новопресіче́. / Но, о Богома́ти, / моле́нія Твої́х рабо́в, / в Твоє́м хра́мі приноси́мая Тебі́, не пре́зри, / но я́ко Благоутро́бнаго Твої́ма рука́ма нося́щи, / на Твоя́ раби́ умилосе́рдися / і моли́ спасти́ся душа́м на́шим."],"h":"Глас 1 — на стиховні Богородичен"},{"ps":["Храм і двер єси́, / пала́та і престо́л Царе́в, / Ді́во Всечестна́я, / Є́юже Ізба́витель мой, Христо́с Госпо́дь, / во тьмі спя́щим яви́ся, / Со́лнце сий пра́вди, просвіти́ти хотя́, / я́же созда́ по о́бразу Своєму́ руко́ю Своє́ю. / Ті́мже, Всепі́тая, / я́ко ма́терне дерзнове́ніє к Нему́ стяжа́вшая, / непреста́нно моли́ спасти́ся душа́м на́шим."],"h":"Глас 5 — на стиховні Богородичен"},{"ps":["Творе́ць і Ізба́витель мой, Пречи́стая, / Христо́с Госпо́дь, із Твої́х ложе́сн проше́д, / в м'я оболки́йся, пе́рвия кля́тви Ада́ма свободи́. / Ті́мже Ті, Всечи́стая, / я́ко Бо́жії Ма́тері же і Ді́ві, / воі́стину вопіє́м немо́лчно: / ра́дуйся, А́нгельськи, ра́дуйся, Влади́чице, / предста́тельство і покро́ве, / і спасе́ніє душ на́ших."],"h":"Глас 6 — на стиховні Богородичен"},{"ps":["Безневі́стная Ді́во, / я́же Бо́га неізрече́нно заче́нши пло́тію, / Ма́ти Бо́га Ви́шняго, / Твої́х рабо́в мольби́ прийми́, Всенепоро́чная, / всім подаю́щи очище́ніє прегріше́ній, / ни́ні на́ша моле́нія приє́млющи, / моли́ спасти́ся всім нам."],"h":"Глас 8 — на стиховні Богородичен"}],"notes":[]},{"u":"Богородичні відпустительні (на «Бог Господь»)","e":"Dismissal theotokia (at “God is the Lord”)","secs":[{"ps":["Чу́до чуде́с, Благода́тная, в Тебі́ зря́щи, / твар ра́дується, / зачала́ бо єси́ безсі́менно / і родила́ єси́ неізрече́нно, / Єго́же чинонача́лія А́нгелов ви́діти не мо́гуть, / Того́ моли́ о душа́х на́ших."],"h":"Глас 1 — у неділю ввечері й у понеділок на «Бог Господь»"},{"ps":["Со А́нгели Небе́сная, с челові́ки земна́я, / гла́сом ра́дованія, Богоро́дице, вопіє́м Ті: / ра́дуйся, врата́, Небе́с ши́ршая; / ра́дуйся, Єди́на земноро́дних спасе́ніє; / ра́дуйся, Чи́стая Благода́тная, / ро́ждшая Бо́га воплоти́вшагося."],"h":"Глас 5 — у неділю ввечері й у понеділок на «Бог Господь»"},{"ps":["Кресто́м Си́на Твоєго́, Богоблагода́тная, / і́дольськая пре́лесть вся упраздни́ся / і де́монськая крі́пость попра́ся. / Сего́ ра́ди, ві́рнії, по до́лгу Тя при́сно поє́м і благослови́м / і, Богоро́дицю воі́стинну іспові́дающе Тя, велича́єм."],"h":"Глас 5 — у вівторок ввечері й у середу на «Бог Господь»"},{"ps":["Нача́ло спасе́нія / Гавриї́лово провіща́ніє к Ді́ві бисть, / сли́ша бо, є́же ра́дуйся, і не убіже́ цілова́нія, / не усумні́ся, я́ко Са́рра в сі́ні, / но си́це глаго́лаше: / се раба́ Госпо́дня, / бу́ди Мні по глаго́лу твоєму́."],"h":"Глас 6 — у неділю ввечері й у понеділок на «Бог Господь»"},{"ps":["Предповіству́єть Гедео́н зача́тіє / і сказу́єть Дави́д Рождество́ Твоє́, Богоро́дице: / сни́де бо, я́ко дождь на руно́, / Сло́во во чре́во Твоє́, / і прозябла́ єси́ без сі́мене, / земле́ свята́я, ми́ра Спасе́ніє, / Христа́ Бо́га на́шего, Благода́тная."],"h":"Глас 6 — у п’ятницю ввечері й у суботу на «Бог Господь»"},{"ps":["Недви́жимоє утвержде́ніє ві́ри / і честни́й дар душ на́ших, / Богоро́дицю пі́сньми велича́єм, ві́рнії: / ра́дуйся, Ка́мень Жи́зні во чре́ві Твоє́м вмісти́вшая; / ра́дуйся, конце́й наде́ждо, скорб'я́щих заступле́ніє; / ра́дуйся, Неві́сто Неневі́стная."],"h":"Глас 8 — у понеділок ввечері й у вівторок на «Бог Господь»"}],"notes":[]},{"u":"Богородичні восьми гласів","e":"Theotokia of the eight tones","secs":[{"ps":["Ді́во Всепі́тая, / ю́же в Тебі́ та́йну Мойсе́й проро́чеськима ви́ді очи́ма, / купину́ горя́щу і неопаля́єму, / Божества́ бо Огнь утро́бу Твою́, Чи́стая, не опали́. / Ті́мже мо́лим Тя я́ко Ма́тер Бо́га на́шего, / мир іспроси́ти ми́рові і ве́лію ми́лость."],"h":"Глас 1 — у понеділок ввечері"},{"ps":["Блудни́цю, і блу́днаго аз, і разбо́йника побіди́х, / і митаря́ прегріше́нії премину́х, і ніневи́тяни. / Уви́ мні, что бу́ду? / ка́ко убі́гну му́ки, аз, окая́нний? / Чи́стая, припа́даю Ті, / уще́дри м'я ми́лостію Твоє́ю, / я́коже о́ния Син Твой спасл єсть."],"h":"Глас 1 — у вівторок зранку"},{"ps":["Воі́стину па́че ума́ / чу́дная Твоя́ вели́чія, рождества́ Твоєго́, Богоневі́сто, / я́же пропові́даша проро́ци всі, / вся пресла́вная, / зача́тіє і рождество́, Всепі́тая, недоми́сленно і несказа́нно, / і́мже мир спасл єсть я́ко Милосе́рд."],"h":"Глас 1 — у п’ятницю ввечері"},{"ps":["Прийді́те, Ма́тер Сві́та, пі́сньми немо́лчними зову́ще, / всі просла́вим, / Та бо ро́ди Спасе́ніє на́ше, / і ра́дуйся принесе́м, я́ко Єди́ной, ро́ждшей всіх Нача́льнейщаго, / І́же пре́жде вік Бо́га; / ра́дуйся, Я́же Є́ву па́дшую па́ки назда́вшая; / ра́дуйся, Пречи́стая Ді́во, Неіскусобра́чная."],"h":"Глас 2 — у суботу зранку"},{"ps":["Ра́дуйся, Сві́та о́блаче; / ра́дуйся, сві́щниче сві́тлий; / ра́дуйся, ру́чко, в не́йже ма́нна; / ра́дуйся, же́зле Ааро́нов; / ра́дуйся, купино́ неопали́мая; / ра́дуйся, черто́же; ра́дуйся, престо́ле; / ра́дуйся, горо́ свята́я; / ра́дуйся, прибі́жище; / ра́дуйся, Боже́ственная трапе́зо; / ра́дуйся, две́ре та́йная; / ра́дуйся, всіх ра́досте."],"h":"Глас 4 — у неділю ввечері"},{"ps":["Стра́шно, і пресла́вно, і ве́ліє та́їнство: / Невмісти́мий во чре́ві вмісти́ся / і Ма́ти по рождестві́ па́ки преби́сть Ді́ва / Бо́га бо роди́, із Нея́ воплоще́нна. / Тому́ возопії́м, Тому́ піснь рцем, / с А́нгели воспіва́юще: / Свят єси́, Христе́ Бо́же, / І́же нас ра́ди вочелові́чивийся, сла́ва Тебі́."],"h":"Глас 5 — у неділю ввечері"},{"ps":["О́ле окая́нная душе́! / Кий отві́т і́маши рещи́ Судії́ во он час, / єгда́ Престо́ли поста́в'яться на Суді́ / і Судія́ при́йдеть от Небе́с, / соше́д со тьма́ми а́нгельськими? / Єгда́ ся́деть на Суди́щі / прю сотвори́ти с раби́ непотре́бними, подо́бними мні, / что отвіща́ти і́маши? / что же принести́ тогда́? / Поі́стинні нічто́же, / ум і ті́ло оскверни́вши твоє́. / Ті́мже припади́ к Ді́ві і зови́ непреста́нно, / пода́ти тебі́ бога́тно гріхо́в проще́ніє."],"h":"Глас 5 — у суботу зранку"},{"ps":["Арха́нгельськи воспої́м, ві́рнії, / Небе́сний черто́г і двер запеча́танну воі́стину: / ра́дуйся, Єя́же ра́ди отрасте́ нам Спас всіх, Христо́с, / Жизнода́вець і Бог, / низложи́, Влади́чице, мучи́телі, / безбо́жния враги́ на́ша / руко́ю Твоє́ю, Пречи́стая, / упова́ніє христия́н."],"h":"Глас 6 — у неділю ввечері"},{"ps":["Ра́дуйся, вселе́нния похвало́; / ра́дуйся, хра́мі Госпо́день; / ра́дуйся, горо́ приосіне́нная; / ра́дуйся, всіх прибі́жище; / ра́дуйся, сві́щниче злати́й; / ра́дуйся, сла́во правосла́вних честна́я; / ра́дуйся, Марі́є, Ма́ти Христа́ Бо́га; / ра́дуйся, раю́; ра́дуйся, Боже́ственная трапе́зо; / ра́дуйся, сі́не; ра́дуйся, ру́чко всезлата́я; / ра́дуйся, всіх упова́ніє."],"h":"Глас 8 — у понеділок ввечері"},{"ps":["Ісхи́ти м'я, Влади́чице, / руки́ змі́я человікоуби́йці, / хотя́ща м'я лука́вством поглоти́ти до конця́; / сокруши́ че́люсти єго́, молю́ Тя, / і ко́зні разори́, / я́ко да, ізби́в от ногте́й єго́, / велича́ю заступле́ніє Твоє́."],"h":"Глас 8 — у четвер зранку"}],"notes":[]}];
export default D;
